INSERT INTO question_papers (id, slug, title, exam_type, focus_tags, question_count, difficulty, is_premium, sort_order, time_limit_minutes)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c5477709-566d-4af6-b2cb-a3d49a8bd20a', '013c7ae5-98cb-4c94-b55c-2755cc85fb28', 0, 'Observation status has its own E/M code considerations (in current CPT structure, often integrated with or closely paralleling hospital inpatient codes depending on the code year/structure), reflecting a distinct administrative/clinical status from formal inpatient admission, even though the patient may be in the same physical hospital bed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d9bb3e5f-1f04-4d5d-9030-07ef4979114d', '013c7ae5-98cb-4c94-b55c-2755cc85fb28', 1, 'Observation and inpatient status are always coded identically with no distinction in CPT');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e3161137-bb46-4931-991e-a7965fc11d27', '013c7ae5-98cb-4c94-b55c-2755cc85fb28', 2, 'Observation status has no corresponding E/M codes at all and is never separately billable');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('67b9fd7c-a799-4f8d-af0a-8129ca31ff3a', '013c7ae5-98cb-4c94-b55c-2755cc85fb28', 3, 'Observation status is determined solely by which floor/unit the patient is physically located on, not by any billing/coding significance');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dfeca198-798e-4632-9c15-5de5349f5c3e', '5af6cc40-2c0b-463a-8d0d-edeb3bc93f19', 0, 'Coding should reflect the actual status timeline as documented (observation-period services, then inpatient-period services following the status change), consistent with the general ''code what actually happened, including status changes'' principle already established for UHDDS/CCS-adjacent status-change scenarios');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('90b2099c-bb64-41fe-8d0c-5dae62382133', '5af6cc40-2c0b-463a-8d0d-edeb3bc93f19', 1, 'The entire stay is always coded as if the patient had been inpatient from the very start, regardless of the actual observation period');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('54f0e59e-7867-4e62-878e-ba37640b8917', '5af6cc40-2c0b-463a-8d0d-edeb3bc93f19', 2, 'The entire stay is always coded as observation only, regardless of the later inpatient conversion');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('88ccdfcf-2b9b-407e-a89b-0b8abbdac4b5', '5af6cc40-2c0b-463a-8d0d-edeb3bc93f19', 3, 'Status changes during a stay have no bearing on E/M code selection for the days before versus after the change');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4e68f55a-e3f0-4414-9ee3-4c14f3e778a7', '5379ac9e-1f91-4534-8e50-0043bf33bccf', 0, 'CPT includes a specific code for the combined same-day admission-and-discharge scenario, reflecting that combined service structure rather than requiring separate admission and discharge codes when both occur on the same calendar date, mirroring the same-day admission/discharge concept already established for standard inpatient care in Paper 3');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3a6394bb-5e6a-4caf-91c0-c0c6c9f10494', '5379ac9e-1f91-4534-8e50-0043bf33bccf', 1, 'Same-day admission and discharge from observation/inpatient status must always be coded as two entirely separate services regardless of date');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c6828e9a-7124-41f5-b735-14256721da0c', '5379ac9e-1f91-4534-8e50-0043bf33bccf', 2, 'This scenario has no distinct CPT code and must use an unlisted E/M code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3302c69f-df29-48ad-8a27-9650ad9e18dc', '5379ac9e-1f91-4534-8e50-0043bf33bccf', 3, 'Same-day admission and discharge coding depends solely on the total length of stay in hours, with no specific combined code available');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b6ed0bd2-5920-4c0d-a218-108bfe77b8f8', 'f06c7603-7fd4-426b-8bcd-73e43cb30625', 0, 'The substantive portion is generally defined as more than half of the total time spent on the visit by the two practitioners combined, or (for certain visit types/years) based on which practitioner performed a certain key MDM-related element — meaning the specific applicable definition should be checked against current-year CMS guidance rather than assumed to be permanently fixed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('80f6f549-b357-408a-bc9d-b9ac786e4a0a', 'f06c7603-7fd4-426b-8bcd-73e43cb30625', 1, 'The substantive portion is always defined as whichever practitioner saw the patient first, regardless of time spent or MDM contribution');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f39e1acf-5dcf-4e2f-a1ba-d0a929805480', 'f06c7603-7fd4-426b-8bcd-73e43cb30625', 2, 'Substantive portion determination has remained completely unchanged since CMS first introduced the concept, with no updates ever made');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fedd9e96-6d5c-4e46-b5e5-e58a5bc4ec61', 'f06c7603-7fd4-426b-8bcd-73e43cb30625', 3, 'The substantive portion is always defined by which practitioner has a higher billing rate, regardless of actual clinical contribution');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b7a02b70-ba94-49e2-8ca9-14bb31cb9e5a', '3641f773-384a-41fe-a7e1-79ff9b53b0cc', 0, 'Each practitioner''s individually documented time spent on the visit should be captured, since the billing determination depends on comparing each practitioner''s actual contributed time against the substantive-portion threshold — a general statement that ''the visit was split'' without individualized time documentation wouldn''t support accurate application of the time-based test');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('47fc3aba-75f9-4c95-afe4-cccc43c82bca', '3641f773-384a-41fe-a7e1-79ff9b53b0cc', 1, 'No time documentation is needed since split/shared visits are always billed under the physician''s NPI regardless of actual time contribution');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('14bbce26-4171-4aca-b849-a6524de158cd', '3641f773-384a-41fe-a7e1-79ff9b53b0cc', 2, 'Only the non-physician practitioner''s time needs to be documented; physician time is assumed by default');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('af203c6e-e510-4c96-b7f0-7c45658da8dc', '3641f773-384a-41fe-a7e1-79ff9b53b0cc', 3, 'Split/shared time documentation requirements are identical to the general E/M time documentation requirements with no split/shared-specific considerations');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('50940f63-2650-4f60-9d73-d2ac1ab9d365', '3e8006d3-c106-4aa3-a1cd-e78f36e14f79', 0, 'Per the substantive-portion principle, this visit would likely be billed under the NP''s NPI (reflecting that the NP performed the substantive majority of the work), rather than automatically defaulting to the physician''s NPI simply because a physician was also involved');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e3ed9fc9-bd2b-4b09-9ca0-3b4a02fcc920', '3e8006d3-c106-4aa3-a1cd-e78f36e14f79', 1, 'The visit must always be billed under the physician''s NPI whenever a physician has any involvement at all, regardless of the NP''s greater substantive contribution');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('91393d50-f506-4281-9e69-19e3d8af577a', '3e8006d3-c106-4aa3-a1cd-e78f36e14f79', 2, 'Split/shared billing is never permitted between a physician and an NP in the same group');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8b3389a9-ae0f-4726-8a99-7c94fd2e227a', '3e8006d3-c106-4aa3-a1cd-e78f36e14f79', 3, 'The visit must be billed twice, once under each practitioner''s NPI, for the same single visit');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6492ef1b-c488-4465-a4f7-bead70a204d1', '5eaf876e-912c-4529-9041-912ed86eb2a1', 0, 'This represents a third, distinct prolonged-service code category (clinical staff time under supervision, for specific qualifying office-based services), separate from both the physician-E/M-time and critical-care-time prolonged service codes already discussed, reinforcing that CPT''s prolonged-services concept spans multiple distinct code families rather than being a single universal add-on');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('803a9308-6319-40fa-b343-86ee93b04f1b', '5eaf876e-912c-4529-9041-912ed86eb2a1', 1, 'All three types of prolonged services (physician E/M, critical care, clinical staff) use the identical single add-on code regardless of context');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('eef25b8f-4f9c-4f65-acc9-cd3acf4c266e', '5eaf876e-912c-4529-9041-912ed86eb2a1', 2, 'Prolonged clinical staff service has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4864fdf0-1ad3-4ab7-a276-5e7f01425296', '5eaf876e-912c-4529-9041-912ed86eb2a1', 3, 'Clinical staff time can never be separately coded as a prolonged service under any CPT convention');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d79d9d94-a9d6-4bd5-9105-48dd92e558b4', 'd179ae24-4643-44c6-87e2-e3145e8399ea', 0, 'The ED E/M code level should reflect the actual work/complexity documented up to the point the patient left, consistent with the general principle that coding reflects actual documented work performed — not automatically defaulting to the lowest or highest possible level regardless of what was actually done and documented');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('18a3d856-83f6-4119-99df-396fcf84d6d3', 'd179ae24-4643-44c6-87e2-e3145e8399ea', 1, 'No E/M code may ever be billed if a patient leaves AMA before full completion of the visit');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ae6e5f29-0f16-4635-8496-44db63ecbcab', 'd179ae24-4643-44c6-87e2-e3145e8399ea', 2, 'The visit is always coded at the highest available ED E/M level regardless of how much workup was actually completed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('05484331-e335-4bfd-a750-e8a5177460f9', 'd179ae24-4643-44c6-87e2-e3145e8399ea', 3, 'AMA departures are coded using a completely separate, unique code unrelated to the standard ED E/M code family');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4c80cc27-bf26-4ea0-b6b7-054f79890e2e', '8d8e13fc-32fe-4fbe-b24f-86fe512bd01c', 0, 'Documentation should reflect that the patient was informed of the risks of leaving before completion of the medical screening/stabilization process (relevant to both EMTALA-adjacent compliance considerations and appropriate E/M coding of the actually-completed work), rather than a bare ''patient left AMA'' notation with no further detail');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('df9e0de5-cc67-4b6e-aba2-45b601c080b8', '8d8e13fc-32fe-4fbe-b24f-86fe512bd01c', 1, 'No specific documentation beyond ''AMA'' is ever relevant to either EMTALA compliance or E/M coding for this scenario');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('610b91c9-464d-48e6-9cf9-68aec0682f19', '8d8e13fc-32fe-4fbe-b24f-86fe512bd01c', 2, 'AMA documentation is relevant only to nursing records, with zero physician documentation or coding relevance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('42461e26-fa64-4c8d-8d10-8392e3c85148', '8d8e13fc-32fe-4fbe-b24f-86fe512bd01c', 3, 'AMA departures automatically exempt a facility from any EMTALA-related documentation considerations');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8d144617-2498-47a5-84f4-1480db448014', 'a3273ecb-2f3c-4af3-8a1f-3cbbb4ed4a93', 0, 'Pediatric/neonatal critical care transport has its own specific code(s), distinct from standard critical care codes and from the neonatal/pediatric inpatient critical care per-day codes already discussed in Paper 3, reflecting this specific transport-based service structure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2365f9a2-231f-4a0a-a025-8fe94c674704', 'a3273ecb-2f3c-4af3-8a1f-3cbbb4ed4a93', 1, 'Critical care transport is coded identically to standard adult critical care time-based codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cf4b3df9-5a59-4f15-aee6-442cf968ca94', 'a3273ecb-2f3c-4af3-8a1f-3cbbb4ed4a93', 2, 'Critical care transport has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2bad48d5-8e27-404f-a08c-50160d66ec19', 'a3273ecb-2f3c-4af3-8a1f-3cbbb4ed4a93', 3, 'Critical care transport is coded using the same code as a routine ambulance transport claim');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fce8b080-55c4-45a9-a7d6-4b28b17b77d2', 'dd937e95-504c-4b38-b8fb-e901348dc7c3', 0, 'Both may be separately reportable — the office visit E/M code (based on its own time/MDM) and the ACP code (based on its own separately-tracked time), consistent with the same-day-multiple-distinct-service principle already established generally, including for ACP specifically in Paper 2');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('14e3e0cd-1089-4f9b-a73a-658d94236035', 'dd937e95-504c-4b38-b8fb-e901348dc7c3', 1, 'Only one of the two services may ever be billed on the same date, regardless of documentation for both');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d7866f89-e381-4d60-853e-f4448a974b3d', 'dd937e95-504c-4b38-b8fb-e901348dc7c3', 2, 'ACP time is always included within the office visit E/M time calculation, never separately trackable');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('acdee4f9-a257-4cc3-9c35-5ffbc64b91e9', 'dd937e95-504c-4b38-b8fb-e901348dc7c3', 3, 'Office visit E/M and ACP must always occur on different calendar dates to both be billable');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('600b4538-a964-407a-a2be-f492f16cffe5', '0473dae0-7761-421e-b5de-573fed682d4e', 0, 'Where a time-threshold distinction exists for discharge day management codes, the total time spent by the physician on discharge-related services that day (final examination, discussion, instructions, discharge summary preparation) determines which specific discharge code level applies');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cb9f3f51-aed4-402f-9fce-4c1ef19d90cc', '0473dae0-7761-421e-b5de-573fed682d4e', 1, 'Discharge day management coding depends solely on the patient''s total length of stay, not the time spent on discharge-day services specifically');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3e87ff0f-632c-4e5c-b6b0-8f18ebc9528f', '0473dae0-7761-421e-b5de-573fed682d4e', 2, 'All discharge day management services are billed using a single flat code regardless of time spent');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1cec647a-de2f-4cdc-b4f0-536c9a60fdd7', '0473dae0-7761-421e-b5de-573fed682d4e', 3, 'Discharge day management is never separately coded from the final day''s regular subsequent hospital care code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('59595e42-cc69-4c45-89ad-403a6899a828', '1359927c-d96d-49f4-973c-65c71c70460b', 0, 'The readmission is coded as its own new encounter, with its own principal diagnosis/E/M service determination based on UHDDS/E/M principles applicable to that specific new admission — coding treats it as a genuine new encounter, separate from any payer-specific readmission-penalty policy analysis (a distinct, non-coding regulatory/payment concept)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1bbe11d2-bee2-495c-baaf-9b0b9ef09df2', '1359927c-d96d-49f4-973c-65c71c70460b', 1, 'Readmissions within a certain timeframe are never separately coded from the original admission');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2b73ff5f-97ef-4a12-94e0-a5b104effa5d', '1359927c-d96d-49f4-973c-65c71c70460b', 2, 'The readmission must always use the identical principal diagnosis code as the original admission, regardless of the actual current reason for this new admission');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a36d1e74-e744-4554-b647-3875fb58f797', '1359927c-d96d-49f4-973c-65c71c70460b', 3, 'Readmission coding is determined solely by whether a payer''s readmission-penalty program applies, not by the actual current clinical circumstances');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8b618367-beb7-44a0-af9f-5256fe576d9a', 'cfdea009-cc00-49e6-b750-98baea65163e', 0, 'Depending on the specific context and whether the patient/family is present, this may fall under specific care-planning/case-management-adjacent codes (e.g., certain care-management or, if patient/family present, prolonged-service-adjacent codes) rather than a standard face-to-face E/M visit code, since the format/participants affect which specific code family applies');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('14992d60-d7a2-4bd3-84b6-1708a1e96703', 'cfdea009-cc00-49e6-b750-98baea65163e', 1, 'Interdisciplinary care conferences are never separately codeable under any CPT convention');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('42de596f-8517-4811-aacc-ae26cc706e8a', 'cfdea009-cc00-49e6-b750-98baea65163e', 2, 'This is always coded using the identical office visit E/M code as a standard face-to-face visit, regardless of the patient''s absence');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fedc7e0f-bd97-43f5-a332-98a2632a03e1', 'cfdea009-cc00-49e6-b750-98baea65163e', 3, 'Only conferences the patient physically attends may ever be considered for any CPT code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('aa04bd8e-d5e4-40fe-acb0-d090cb4abbbb', '6d55be03-dab7-4d03-bdf5-7166afddc5eb', 0, 'Identify the SPECIFIC status/timeline/participant structure actually documented (status at each point in time, each practitioner''s actual contribution, the actual reason for a new encounter) and match it to the E/M code family/rule reflecting that specific structure — consistent with the disciplined, documentation-specific analytical approach already established throughout this content''s E/M-section coverage');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('eeee18a3-d897-4325-9ce4-06656229f22d', '6d55be03-dab7-4d03-bdf5-7166afddc5eb', 1, 'Assume all hospital-based E/M scenarios are billed identically regardless of status changes, practitioner mix, or encounter timing');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bd4ced93-65d3-4965-8a44-2fc7ad5a6ad8', '6d55be03-dab7-4d03-bdf5-7166afddc5eb', 2, 'Status changes, split/shared billing, and readmissions are edge cases with no real-world coding relevance worth understanding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7c73b322-8ce9-4ddc-83ca-49d20f677ea5', '6d55be03-dab7-4d03-bdf5-7166afddc5eb', 3, 'Rely on the hospital''s internal billing system default settings rather than the actual documented clinical/administrative facts');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bb393219-cbc3-4322-a17a-e2cda67001ef', 'bd8296a4-7193-41d6-8307-34b1caa4b7f5', 0, 'A consultation code may be appropriately reported (reflecting the request-reason-report structure already discussed) since this payer recognizes consultation codes and the scenario meets the substantive consultation criteria — a different outcome than the Medicare/non-recognizing-payer scenario already covered');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7a60fb5a-9adf-499d-b516-ad3788560347', 'bd8296a4-7193-41d6-8307-34b1caa4b7f5', 1, 'Consultation codes may never be used regardless of payer policy, following the Medicare-specific rule universally across all payers');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('97577340-1e74-48b1-9d59-badbe29e47a6', 'bd8296a4-7193-41d6-8307-34b1caa4b7f5', 2, 'The requesting attending, not the consulting physician, always bills for the consultation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2a954dde-56c6-46a3-b763-9bf31f109590', 'bd8296a4-7193-41d6-8307-34b1caa4b7f5', 3, 'Consultation codes require the consulting physician to assume ongoing primary responsibility for the patient''s total care, converting it into a transfer-of-care scenario automatically');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('12a61866-2c20-4272-9a94-5e8f77ad03ff', 'df329ab1-4a6f-4535-b2b2-787cd6f12f49', 0, 'A consultation involves a request for the consultant''s opinion/advice on a specific problem, with care of that problem generally remaining with the requesting physician, while a transfer of care involves the second physician assuming ongoing management responsibility for the condition — a genuinely different clinical/billing relationship affecting which E/M code family applies');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ec12fd52-d175-404e-8fe6-4d1569b18933', 'df329ab1-4a6f-4535-b2b2-787cd6f12f49', 1, 'Consultation and transfer of care are simply two different names for the identical clinical/billing scenario');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3ff99cf9-c8fc-4344-b6dc-a6abd2059a44', 'df329ab1-4a6f-4535-b2b2-787cd6f12f49', 2, 'Transfer of care always requires a formal legal document, while consultation requires no such documentation ever');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('55121210-3203-42e4-a393-0ce23e9fedff', 'df329ab1-4a6f-4535-b2b2-787cd6f12f49', 3, 'The distinction between consultation and transfer of care has been eliminated entirely from current CPT E/M guidance');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('698894b2-521e-4b69-94f5-b19c74d20389', 'a93d810e-3fc3-45f7-b83a-df80f6543aa3', 0, 'The initial encounter (genuine consultation, care remaining with the requester at that time) may appropriately be coded as a consultation, with SUBSEQUENT encounters (after the physician has assumed ongoing management) coded using standard established-patient E/M codes reflecting the now-changed clinical relationship, rather than continuing to use consultation codes indefinitely once the relationship has genuinely changed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f6b138be-70a7-4f5f-a633-67a362096a7d', 'a93d810e-3fc3-45f7-b83a-df80f6543aa3', 1, 'Every subsequent encounter must continue to be coded as a consultation indefinitely, regardless of the changed clinical relationship');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3bd1e0c7-dfd9-4aa5-b54e-71781fef9417', 'a93d810e-3fc3-45f7-b83a-df80f6543aa3', 2, 'The initial consultation must be retroactively recoded as a transfer of care once the physician later assumes management');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cc4e1102-5b2c-4671-80a8-34fd34023dcd', 'a93d810e-3fc3-45f7-b83a-df80f6543aa3', 3, 'This scenario can never occur under any CPT E/M convention');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f6657579-9cc8-45c4-b238-4cd3649e030a', '4ee1d765-3e9b-40b6-8eb6-61192bdf1a79', 0, 'E/M coding accuracy frequently depends not just on WHAT service was performed, but on accurately characterizing WHO performed which portion of the work and WHAT the clinical/administrative relationship or status actually was AT THE SPECIFIC TIME of the encounter — a recurring theme distinct from, but complementary to, the time/MDM-based leveling concepts covered extensively elsewhere in the E/M content');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('35b833d2-e29b-4435-8a7c-8c2b83dd5fe3', '4ee1d765-3e9b-40b6-8eb6-61192bdf1a79', 1, 'E/M coding depends solely on time/MDM leveling, with relationship/status/practitioner-role questions being irrelevant edge cases');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('28556f02-1741-4881-8321-0ae88d5f2e1a', '4ee1d765-3e9b-40b6-8eb6-61192bdf1a79', 2, 'Who performed the service and what the clinical relationship was are considerations that apply only to consultation coding, with no relevance to split/shared or status-change scenarios');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6c926c88-55e0-420e-88db-59f457d8b7f9', '4ee1d765-3e9b-40b6-8eb6-61192bdf1a79', 3, 'Accurately characterizing relationships and timelines is solely a legal/compliance concern with no actual bearing on which specific CPT code is correct');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('172ca117-1ab9-4d2e-adb8-8c2f19febcc0', '139c7444-f98f-49f6-bfb8-fb183046313a', 0, 'The consultant appropriately bills the consultation code for their one-time opinion/recommendation, since care of the condition remained with the requesting physician throughout — a clean example of the consultation (not transfer of care) relationship structure already discussed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2d85c4a8-266e-4ac2-9602-00142bd05f27', '139c7444-f98f-49f6-bfb8-fb183046313a', 1, 'The consultant must bill using a transfer-of-care E/M code since a treatment recommendation was made');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dd3e1f7d-ffff-43d0-91c1-0c95c8f2b82a', '139c7444-f98f-49f6-bfb8-fb183046313a', 2, 'Only the requesting physician may bill anything for this scenario; the consultant''s work is never separately billable');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d26e3a09-5fe3-4419-8b08-2b24df3d6b37', '139c7444-f98f-49f6-bfb8-fb183046313a', 3, 'This scenario requires the consultant to perform the recommended treatment personally in order to bill anything at all');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9c3494be-6f48-4181-9342-17fdf39050dd', 'af46b7ee-c7ac-4652-ae72-d7140e3a8ae6', 0, 'A specific qualifying circumstances add-on code exists for anesthesia complicated by emergency conditions (defined as existing when delay in treatment would significantly increase the threat to life or body part), reported in addition to the base anesthesia code when this circumstance is genuinely documented');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8240759c-a978-465e-bfd8-bd98c6c29dd5', 'af46b7ee-c7ac-4652-ae72-d7140e3a8ae6', 1, 'Emergency conditions have no distinct qualifying circumstances code and are simply reflected via a higher physical status modifier alone');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9a14c02b-3528-4966-aebc-75c7820d271b', 'af46b7ee-c7ac-4652-ae72-d7140e3a8ae6', 2, 'Trauma anesthesia is always billed using an entirely separate, unrelated anesthesia code set from elective surgical anesthesia');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a8c32820-8968-4695-94a7-2e046bafcdce', 'af46b7ee-c7ac-4652-ae72-d7140e3a8ae6', 3, 'Emergency-condition qualifying circumstances codes apply only to pediatric trauma patients, never adults');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e07233c3-7ab6-4e72-a66e-ef86be39c99d', '7612cb12-34d0-494a-a6dd-1bd5c60d1296', 0, 'The physical status modifier should reflect the patient''s actual, severe physiologic condition at the time of anesthesia (e.g., a higher-severity P-modifier reflecting severe systemic disease/life-threatening condition), consistent with the general principle that physical status modifiers reflect genuine documented patient condition, not a default/routine selection');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3d62964d-5cd2-47ad-818c-049630ebc014', '7612cb12-34d0-494a-a6dd-1bd5c60d1296', 1, 'Physical status modifiers are always P1 for trauma cases regardless of actual physiologic instability');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c850c401-76da-48e5-8b69-30684d3d86ea', '7612cb12-34d0-494a-a6dd-1bd5c60d1296', 2, 'Trauma cases are exempt from physical status modifier selection entirely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4c09e2aa-4905-4e3b-b2bb-c75fc673c250', '7612cb12-34d0-494a-a6dd-1bd5c60d1296', 3, 'Physical status modifier selection depends solely on the type of injury, not the patient''s overall systemic physiologic status');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d59c94f4-a135-446e-9f7b-76e5d33837cc', 'c71cd52e-450c-4426-9975-350e73b67f23', 0, 'Both qualifying circumstances add-on codes may be reported together when both circumstances are genuinely present and documented, since these represent independently-defined complicating circumstances that can co-occur in the same case, consistent with the general principle that add-on codes are reported for each qualifying circumstance actually present');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bdcb003a-667b-490d-867c-18a3e86c50eb', 'c71cd52e-450c-4426-9975-350e73b67f23', 1, 'Only one qualifying circumstances code may ever be reported per case, regardless of how many genuinely apply');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('46e9f2b9-46a7-4945-b1bf-0b6d820573b4', 'c71cd52e-450c-4426-9975-350e73b67f23', 2, 'Age and emergency-condition qualifying circumstances are mutually exclusive and can never both apply to the same patient');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8eba4a6d-cac1-4532-b3bd-e12a699e01fa', 'c71cd52e-450c-4426-9975-350e73b67f23', 3, 'Combining two qualifying circumstances codes automatically triggers an NCCI edit requiring a bypass modifier');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('43b6e33e-7128-4a8d-9a64-6f0af8d275d4', 'f23e780a-4a58-4117-b7ef-7ef7e839e4c8', 0, 'Documentation should reflect the specific clinical basis for the emergency determination (e.g., that delay would have significantly increased threat to life or body part), since this qualifying circumstances code has its own specific defined threshold — not simply any case labeled ''urgent'' or ''emergent'' by scheduling convention automatically qualifies without that specific clinical basis being documented');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d8cf53e6-344a-4acc-8cba-b3e73fcc5b12', 'f23e780a-4a58-4117-b7ef-7ef7e839e4c8', 1, 'Any case scheduled as ''emergency'' or ''urgent'' on the OR schedule automatically qualifies for this code regardless of the actual clinical documentation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c2655604-09fc-4523-a8e2-b9f07ecd5fd0', 'f23e780a-4a58-4117-b7ef-7ef7e839e4c8', 2, 'No specific documentation is needed since emergency status is assumed for any trauma-related surgery');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0441829e-febc-4d81-8383-00f19709e317', 'f23e780a-4a58-4117-b7ef-7ef7e839e4c8', 3, 'This qualifying circumstances code requires no clinical justification beyond the anesthesiologist''s own verbal assertion at the time of billing');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9fabf1ac-6ab8-4a88-ab12-d489113b79a9', '29caaf41-d7a8-4a5d-87c6-95b895815cad', 0, 'The initial damage-control procedure''s anesthesia is coded based on the procedure(s) actually performed at that session, with the LATER, planned return-to-OR procedure for definitive repair coded as its own separate anesthesia service at that later session — consistent with the general principle that each distinct operative session''s anesthesia is coded based on what was actually performed at that specific session');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('40477ff0-2d8d-4461-8e79-3608380d9e5c', '29caaf41-d7a8-4a5d-87c6-95b895815cad', 1, 'A single anesthesia code covers both the initial damage-control surgery and the later definitive repair regardless of how much time elapses between them');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8c28bc77-5cbc-40f4-8cc6-90087a71e11b', '29caaf41-d7a8-4a5d-87c6-95b895815cad', 2, 'Damage-control surgery anesthesia has no distinct coding treatment from a routine single-session elective procedure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cc82baab-b76f-4e0d-8547-d3dd8948902d', '29caaf41-d7a8-4a5d-87c6-95b895815cad', 3, 'The later definitive repair procedure''s anesthesia is never separately coded since it was ''planned'' at the time of the initial surgery');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1c11ee6a-66aa-4b13-93b7-9a60bd63d043', 'bae91a7a-0fff-40b1-8bc3-1dd21b8216bf', 0, 'Apply the same core anesthesia-coding analytical framework already established throughout this content — base code by procedure/region, physical status modifier reflecting actual documented patient condition, and qualifying circumstances add-on codes for each genuinely documented complicating factor (age, emergency conditions, hypothermia, etc.) — recognizing that trauma/emergency scenarios frequently involve MULTIPLE genuinely applicable qualifying circumstances rather than requiring an entirely different coding framework');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('98e82b62-e4e7-40c6-86cd-5e3711708f7c', 'bae91a7a-0fff-40b1-8bc3-1dd21b8216bf', 1, 'Trauma anesthesia requires an entirely separate, unrelated coding framework from the general anesthesia coding principles established elsewhere in this content');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6ed32147-9429-4993-bc30-3d8b9b61303a', 'bae91a7a-0fff-40b1-8bc3-1dd21b8216bf', 2, 'Emergency qualifying circumstances automatically override and replace the need for accurate physical status modifier selection');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5006ce15-9770-4101-bd7a-a4fd6d270520', 'bae91a7a-0fff-40b1-8bc3-1dd21b8216bf', 3, 'Trauma/emergency anesthesia coding is determined solely by the total anesthesia time, with no relevance for procedure/region, physical status, or qualifying circumstances');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a94cfa6b-745f-439b-a485-229b9646071c', '9d8a2fdf-429f-4e34-9563-f9ef0171abe0', 0, 'The appropriate obstetric anesthesia code for cesarean delivery is reported, with the emergency-conditions qualifying circumstances add-on code also appropriately reportable if the specific clinical threshold for that qualifying circumstance is genuinely documented, combining the obstetric-anesthesia and emergency-qualifying-circumstances concepts already established separately');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('897e8a47-94d7-4dea-9b40-b76be65bb77f', '9d8a2fdf-429f-4e34-9563-f9ef0171abe0', 1, 'Obstetric emergencies are exempt from ever using the emergency-conditions qualifying circumstances code, regardless of documented severity');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b889ee09-5df0-453d-bed3-3bca86e67d78', '9d8a2fdf-429f-4e34-9563-f9ef0171abe0', 2, 'Emergency cesarean delivery anesthesia is coded using a general trauma anesthesia code rather than the obstetric-specific cesarean delivery code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('982054cd-4827-4a73-8ae7-27ffffe7acfd', '9d8a2fdf-429f-4e34-9563-f9ef0171abe0', 3, 'Obstetric anesthesia codes can never be combined with any qualifying circumstances add-on code under any documented circumstance');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b808eba9-12d3-48b7-b3c4-7af9c7a81fa3', '8bb56029-74a8-4b80-a949-16c3d8f4caa6', 0, 'Documentation should clearly delineate each distinct procedure/session and the anesthesia time/circumstances specific to each, since accurate coding depends on correctly attributing anesthesia time/qualifying circumstances to the SPECIFIC procedure(s) actually performed during each distinct anesthesia episode, even amid a chaotic, fast-moving clinical scenario');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b25401e3-9dad-49ad-9d86-8bc50dad9939', '8bb56029-74a8-4b80-a949-16c3d8f4caa6', 1, 'Mass casualty scenarios are exempt from normal anesthesia documentation standards given the chaotic circumstances');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('39528665-bb9c-4152-97f8-65fd190e7144', '8bb56029-74a8-4b80-a949-16c3d8f4caa6', 2, 'A single generic anesthesia code covers all procedures performed on a patient during a mass casualty event regardless of number/type of distinct procedures');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('446c7639-8ef3-46d1-ac94-1caef4d33ee2', '8bb56029-74a8-4b80-a949-16c3d8f4caa6', 3, 'Time documentation is unnecessary in emergency/trauma scenarios since qualifying circumstances codes alone are assumed sufficient');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ecc9476b-aeef-488e-a5d5-629466ea006c', 'd22523ab-122c-44e7-aef2-6d44d28a15ed', 0, 'The appropriate anesthesia code for the specific interventional radiology procedure/region is reported, with the emergency-conditions qualifying circumstances add-on code also appropriately reportable when genuinely documented, connecting the Paper 3 interventional-radiology-anesthesia concept with this paper''s emergency-qualifying-circumstances concept');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('77631de5-6372-4ffa-88d8-caa1cedf2f76', 'd22523ab-122c-44e7-aef2-6d44d28a15ed', 1, 'Anesthesia for emergency interventional radiology procedures has no distinct code and must use an unlisted anesthesia procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e13003d1-d0e5-4f43-b382-52ac22318ef3', 'd22523ab-122c-44e7-aef2-6d44d28a15ed', 2, 'Emergency interventional radiology anesthesia is coded identically to emergency general surgery anesthesia regardless of the specific procedure/region');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('130eab97-326c-4041-9459-a85c0f3c7c32', 'd22523ab-122c-44e7-aef2-6d44d28a15ed', 3, 'Qualifying circumstances codes apply only to open surgical procedures, never interventional/minimally invasive procedures');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7a33f4c2-e483-4c04-aa5d-8e620be359b8', '8f8cf9b6-d2fd-48ab-af76-da5a764eb95e', 0, 'Given that these add-on codes increase reported complexity/reimbursement, periodic review of whether qualifying circumstances codes are consistently well-documented (genuine clinical basis present, not applied routinely/by default) is a reasonable compliance practice, consistent with the general documentation-support-required principle already established for these specific codes throughout this content');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('70e3c8dd-180a-41e8-bc80-47552e0e2730', '8f8cf9b6-d2fd-48ab-af76-da5a764eb95e', 1, 'Qualifying circumstances codes carry no distinct compliance considerations from any other anesthesia code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2e3fff72-4d51-4e37-8561-dbdb46adc205', '8f8cf9b6-d2fd-48ab-af76-da5a764eb95e', 2, 'These codes should be applied to every anesthesia case by default to ensure no reimbursement is missed, regardless of documented clinical basis');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3af7c798-1b39-4eeb-90c4-7f6c402e12f3', '8f8cf9b6-d2fd-48ab-af76-da5a764eb95e', 3, 'Compliance review of qualifying circumstances coding is unnecessary since these codes have no impact on overall anesthesia reimbursement');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('22caf390-2058-4826-ad2c-4ad3e06244b2', '3c4f58e5-dbbd-4715-bfc6-46bf6c3035b0', 0, 'Craniotomy codes are generally selected based on the specific INDICATION/procedure performed through the craniotomy (tumor resection vs. hematoma evacuation vs. other purposes), since the craniotomy approach itself is often coded together with, or specific to, the underlying procedure''s purpose rather than a single universal ''craniotomy'' code regardless of indication');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cd8890a1-70e7-4cf5-8d02-69dd22712fa8', '3c4f58e5-dbbd-4715-bfc6-46bf6c3035b0', 1, 'All craniotomies, regardless of indication, are coded using a single universal code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('81a3bf87-1b02-40b7-9e60-7f1879b4fa65', '3c4f58e5-dbbd-4715-bfc6-46bf6c3035b0', 2, 'Craniotomy for tumor resection is coded identically to craniotomy for hematoma evacuation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ee1df779-390b-46ea-819b-848a99d5aaa0', '3c4f58e5-dbbd-4715-bfc6-46bf6c3035b0', 3, 'Craniotomy coding depends solely on which side of the skull is opened, not the underlying indication/procedure performed');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('45371876-3de0-42ea-8ff0-c694004856ff', 'f1505fe5-bf54-4843-baa3-7f9096a7ecd4', 0, 'Stereotactic (image-guided, minimally invasive, typically needle-based) biopsy has its own specific code, distinct from an open craniotomy approach to biopsy the same type of lesion, reflecting the different technique/invasiveness — consistent with the approach-specificity theme already established throughout this content');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('432e7c5e-c859-4ddd-b112-fd2c80ad9299', 'f1505fe5-bf54-4843-baa3-7f9096a7ecd4', 1, 'Stereotactic and open craniotomy biopsy are always coded identically regardless of approach');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('83391cec-41d0-4f2e-b7d7-dd01e8cb9803', 'f1505fe5-bf54-4843-baa3-7f9096a7ecd4', 2, 'Stereotactic biopsy has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d6d4d4fb-bbc2-4170-99df-0115d8fb4737', 'f1505fe5-bf54-4843-baa3-7f9096a7ecd4', 3, 'Stereotactic biopsy coding depends solely on the lesion''s size, not the technique/approach used');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7a141ecc-a4d5-43ac-a5ed-5b68e3e0b88e', 'a8ce48e0-0139-4913-a3ed-6948cf937d5a', 0, 'Whether the laminectomy is separately reportable or considered a bundled component of the fusion procedure depends on the specific code descriptors/NCCI edits for that combination, consistent with the general bundling-analysis principle already established — laminectomy performed as a distinct, standalone decompression procedure (not part of a fusion) is coded on its own merits');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8d5cee9d-1ab9-4c54-aca9-67684a7f7b0c', 'a8ce48e0-0139-4913-a3ed-6948cf937d5a', 1, 'Laminectomy is always separately reportable in full regardless of whether a fusion is performed at the same session');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a9ba8e14-e4bc-4cd3-9bbd-18922d6e2a57', 'a8ce48e0-0139-4913-a3ed-6948cf937d5a', 2, 'Laminectomy is always bundled into any spinal fusion code with no separate reporting ever possible under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a47499d6-42dc-4026-920c-4d1b6e609a83', 'a8ce48e0-0139-4913-a3ed-6948cf937d5a', 3, 'Laminectomy has no distinct CPT code and must always use an unlisted procedure code regardless of context');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dd9f7558-518c-4bd2-9cf9-bd950600008d', '2bc3b165-1e6b-4203-8111-796e12655f2a', 0, 'Spinal fusion codes commonly distinguish by surgical approach (anterior vs. posterior vs. lateral, among others), reflecting genuinely different surgical techniques/exposures for achieving fusion, consistent with the approach-specificity theme already established generally');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('18ec67de-3b2c-4fa1-8c6c-554d4f676e4f', '2bc3b165-1e6b-4203-8111-796e12655f2a', 1, 'Anterior and posterior spinal fusion are coded identically regardless of approach');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8b2818a6-2a24-4e60-b399-0c92f2145acd', '2bc3b165-1e6b-4203-8111-796e12655f2a', 2, 'Only posterior spinal fusion has a CPT code; anterior fusion must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9119e7bc-e997-49b1-90b8-92d16b5c6da9', '2bc3b165-1e6b-4203-8111-796e12655f2a', 3, 'Spinal fusion approach has no bearing on CPT code selection, only the number of levels fused does');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('602220a2-db62-49a7-8711-94a94f1fe677', '572b0a8c-301b-4945-8972-631592828ded', 0, 'Spinal instrumentation placement generally has its own specific add-on or component code(s), separately reportable in addition to the fusion procedure code itself, reflecting the same base-procedure-plus-device-component coding pattern already established generally for other procedures involving both a base procedure and device placement');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('97b5b142-d79a-4b49-83d0-4880dd732c04', '572b0a8c-301b-4945-8972-631592828ded', 1, 'Spinal instrumentation is always included in the base fusion code with no separate reporting ever possible');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8c542843-5ed7-4552-b668-737d0671ec91', '572b0a8c-301b-4945-8972-631592828ded', 2, 'Instrumentation placement is coded identically to the laminectomy/decompression portion of the procedure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('978a07b5-61e0-4cf1-92da-7dc24703a45b', '572b0a8c-301b-4945-8972-631592828ded', 3, 'Spinal instrumentation has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
