INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('500fafd0-2d76-49e0-b954-f8a4b327c4ce', '05db692c-978d-4ca3-87e4-3adcc312b89a', 0, 'CPT commonly distinguishes initial hernia repair from repair of a RECURRENT hernia (one that has previously been surgically repaired and has recurred), using different codes reflecting the generally increased complexity of recurrent repair, similar to how other procedures in this content distinguish coding by documented complexity/history');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('39b7356d-50a8-4ecc-a5cf-96d29cf27532', '05db692c-978d-4ca3-87e4-3adcc312b89a', 1, 'Initial and recurrent hernia repair are always coded identically regardless of surgical history');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('234e9cb9-70b1-44c3-8e44-4a089afddf0b', '05db692c-978d-4ca3-87e4-3adcc312b89a', 2, 'Only recurrent hernia repair has a CPT code; initial repair must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ef06e6fe-5c45-4fd4-9126-3e803afb9ca8', '05db692c-978d-4ca3-87e4-3adcc312b89a', 3, 'Recurrent hernia repair coding depends solely on the patient''s age, not the surgical history');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
