INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7ace9f41-dd55-4069-b832-72d1a30500b6', 'f2e84f5e-0ef8-4e4b-b024-3ec821dca1c6', 0, 'Mesh use may be reflected via the specific hernia repair code selected (some hernia repair codes specifically account for mesh use in their own descriptor) or via a separate add-on/component code, depending on the specific hernia type/code structure — mirroring the general ''device/material use is a documented, code-relevant detail'' principle already established generally for other procedures (e.g., Supplement in ICD-10-PCS)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e7af0aed-a715-4294-82e4-ef94ac7ff763', 'f2e84f5e-0ef8-4e4b-b024-3ec821dca1c6', 1, 'Mesh use has no bearing on CPT hernia repair code selection under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f7d5922a-26aa-43ee-9246-3f44a6cbca4a', 'f2e84f5e-0ef8-4e4b-b024-3ec821dca1c6', 2, 'All hernia repairs, with or without mesh, are coded identically');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('15c907dd-371d-4754-9a47-d2897d444b3a', 'f2e84f5e-0ef8-4e4b-b024-3ec821dca1c6', 3, 'Mesh-reinforced hernia repair has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
