INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e82844ed-d21c-4566-af6a-19488665f10a', '99c29e60-b64a-4f74-a7ac-e7759906811c', 0, 'Laparoscopic and open inguinal hernia repair have distinct codes reflecting the different surgical approach, consistent with the approach-specificity theme already established repeatedly throughout this content');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7f29309f-9101-4cc7-b9f3-68aaea116ddd', '99c29e60-b64a-4f74-a7ac-e7759906811c', 1, 'Laparoscopic and open hernia repair are always coded identically regardless of approach');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0244b652-3680-4591-962e-ae1c35cb20ed', '99c29e60-b64a-4f74-a7ac-e7759906811c', 2, 'Only open hernia repair has a CPT code; laparoscopic repair must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d554411c-f420-4209-a34f-42c9059de346', '99c29e60-b64a-4f74-a7ac-e7759906811c', 3, 'Approach (laparoscopic vs. open) is relevant only to hernia repair recovery time, not to CPT code selection');
