INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('627d47ba-614b-480f-b99b-fb1bf01e4d7f', '818e3e13-642e-48d8-afef-f1fd2cf82a31', 0, 'Bilateral hernia repair, similar in concept to other bilateral procedures already discussed, may be coded using modifier 50 (bilateral procedure) appended to the appropriate unilateral hernia repair code, OR via a specific bilateral hernia repair code if one exists for that specific hernia type/approach — requiring the coder to check the specific code''s own structure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('47a22c97-a662-4fda-be15-aa37b20f2c4e', '818e3e13-642e-48d8-afef-f1fd2cf82a31', 1, 'Bilateral hernia repair is always coded using two entirely separate, unrelated codes with no bilateral modifier or combined-code option ever available');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c9cec994-7dff-4661-af01-9b338dd037e4', '818e3e13-642e-48d8-afef-f1fd2cf82a31', 2, 'Only one side''s repair is ever coded when bilateral repair is performed, with the other side''s repair disregarded');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('be3c2f4e-12ef-442e-b39f-e2a2169e9cb2', '818e3e13-642e-48d8-afef-f1fd2cf82a31', 3, 'Bilateral hernia repair coding depends solely on the patient''s total operative time, not the number of sides repaired');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
