INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7fc2225f-2193-4ffb-a000-6b3aab101cb5', '27e90bdb-1547-48d2-9ae5-4cfda2cd5e02', 0, 'CPT may distinguish pediatric from adult umbilical hernia repair by age threshold or by reducible-versus-incarcerated status, similar to how other procedures in this content (e.g., tonsillectomy) reflect age-based or complexity-based code distinctions');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fb3dc035-929d-4863-a453-9a6b0a6c86ac', '27e90bdb-1547-48d2-9ae5-4cfda2cd5e02', 1, 'Umbilical hernia repair is always coded identically regardless of patient age or incarceration status');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9cad15df-d984-4d63-975e-7d294a4b3067', '27e90bdb-1547-48d2-9ae5-4cfda2cd5e02', 2, 'Pediatric umbilical hernia repair has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('55379752-2c15-4e3c-a970-0b75db8db40d', '27e90bdb-1547-48d2-9ae5-4cfda2cd5e02', 3, 'Umbilical hernia repair coding depends solely on hernia size in centimeters, with no age or incarceration-status distinction ever made');
