INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3ec19ed4-fc30-467f-af05-7b848191be77', '5772a53d-f53b-459c-b55a-3966af21d0bb', 0, 'Incarcerated/strangulated hernia repair (where the hernia contents cannot be reduced, potentially compromising blood supply) generally has its own specific code reflecting the increased complexity/urgency of this presentation, distinct from a routine, reducible hernia repair code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('09f9a15f-a1e5-45cd-8ec3-b91450378516', '5772a53d-f53b-459c-b55a-3966af21d0bb', 1, 'Incarcerated and reducible hernia repair are always coded identically regardless of the hernia''s clinical presentation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ebc5185b-fdb4-4dd0-a6ee-9eabfc871b85', '5772a53d-f53b-459c-b55a-3966af21d0bb', 2, 'Incarcerated hernia repair has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dac3b494-2caf-449b-b692-b63e69da19d5', '5772a53d-f53b-459c-b55a-3966af21d0bb', 3, 'Incarceration status is relevant only to the urgency of scheduling, never to CPT code selection');
