INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7c9083aa-14f9-45f6-b5c2-3d32695b8033', 'e421e703-5b1f-4930-b2e7-6041ad049ac9', 0, 'The bowel resection may be separately reportable in addition to the hernia repair code, since this represents genuinely distinct additional surgical work (addressing non-viable bowel) beyond the hernia repair itself — consistent with the general ''genuinely distinct additional procedural component'' separate-reportability principle already established throughout this content');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('414e0300-77e9-4f65-8f89-93a0fcd64619', 'e421e703-5b1f-4930-b2e7-6041ad049ac9', 1, 'Bowel resection performed during a hernia repair is always bundled into the hernia repair code regardless of the extent of additional work performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e3d75fcd-d3b2-4c97-a9c3-05c9b70f4d1b', 'e421e703-5b1f-4930-b2e7-6041ad049ac9', 2, 'Only the bowel resection is ever coded, with the hernia repair itself considered bundled into it');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('64b30947-33a7-428d-882d-9c93f64fa1e4', 'e421e703-5b1f-4930-b2e7-6041ad049ac9', 3, 'Bowel resection during hernia surgery has no distinct CPT code and must use an unlisted procedure code');
