INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f894cf03-9151-4fe7-b542-b321905b3231', '9db60d2f-2fda-469d-b61b-e953304b553b', 0, 'Lumbar puncture codes may distinguish diagnostic from therapeutic purpose, similar to the diagnostic-versus-therapeutic qualifier distinction already established generally for other drainage-type procedures (thoracentesis, paracentesis)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('81c8cd31-c989-40df-8aa8-4a9ec60577c9', '9db60d2f-2fda-469d-b61b-e953304b553b', 1, 'Diagnostic and therapeutic lumbar puncture are always coded identically regardless of purpose');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('53fc8c09-4741-4c9c-b6d2-90ab2fe0728b', '9db60d2f-2fda-469d-b61b-e953304b553b', 2, 'Lumbar puncture has no distinct CPT code and must use an unlisted procedure code regardless of purpose');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bd74257d-6cb1-411c-bebc-67fadcc2854b', '9db60d2f-2fda-469d-b61b-e953304b553b', 3, 'Lumbar puncture purpose (diagnostic vs. therapeutic) is relevant only to the interpreting pathologist, never to the performing physician''s procedure code');
