INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ea46e80a-e68d-4672-a8f6-88a1818ed5bc', '55a0983e-8a74-4f09-a5fa-d023ed4f73e3', 0, 'VP shunt placement has its own specific code reflecting this distinct neurosurgical procedure (creating a route for CSF drainage from the ventricles to the peritoneal cavity), consistent with the Bypass-type routing concept already established generally (though coded via its own specific Surgery-section code rather than a generic ''bypass'' code)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('da06b60c-31c1-45ff-bbf6-72f5a350b2ab', '55a0983e-8a74-4f09-a5fa-d023ed4f73e3', 1, 'VP shunt placement is coded identically to a lumbar puncture');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2f6de253-191c-410a-a061-d7fba1b83a60', '55a0983e-8a74-4f09-a5fa-d023ed4f73e3', 2, 'VP shunt placement has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a1fbd9f0-0132-4587-9145-29dfaf6f4168', '55a0983e-8a74-4f09-a5fa-d023ed4f73e3', 3, 'VP shunt placement is coded using the same code as external ventricular drain placement');
