INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ec34fc39-c32a-4f1b-a253-b65108a7cccc', 'cac23bed-45bc-4c97-88d1-7092f1ff4d43', 1, 'Shunt revision is always included in the original placement code''s global period regardless of how much later it occurs');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('87e2338a-eafb-48e9-980f-63e5116121d2', 'cac23bed-45bc-4c97-88d1-7092f1ff4d43', 2, 'Shunt revision is coded identically to initial shunt placement');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f66904ae-69bc-489a-958e-968fe42d1596', 'cac23bed-45bc-4c97-88d1-7092f1ff4d43', 3, 'Shunt revision has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
