INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('61704cd6-7ec9-4ad2-a39e-76274596499b', '4adc514c-4623-42de-ad3b-47112e78f69d', 0, 'Apply the same core analytical discipline already established throughout this content — specific indication/procedure performed, approach (open vs. minimally invasive, anterior vs. posterior), device/material use (mesh, instrumentation), and complexity/history factors (recurrent, incarcerated) — matching these specifics to the precise code descriptor, consistent with the disciplined approach used across all Surgery-section content in this series');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('091ec892-f319-4e2a-871f-7993dd7c831d', '4adc514c-4623-42de-ad3b-47112e78f69d', 1, 'Neurosurgical and hernia procedures require an entirely separate, unrelated analytical approach from other Surgery-section coding already covered');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9618293a-f1ac-4969-be8f-43499fdc4b92', '4adc514c-4623-42de-ad3b-47112e78f69d', 2, 'Assume all procedures within the same broad category (e.g., ''brain surgery'' or ''hernia repair'') are coded identically regardless of documented specifics');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('642b07c2-d7de-450a-9924-42c867670df4', '4adc514c-4623-42de-ad3b-47112e78f69d', 3, 'Rely on the surgeon''s own preferred procedure name/shorthand rather than reviewing the actual documented technique against code descriptors');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
