INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cc27b25a-1616-421b-a9e1-e9e0065c2df9', '30d314fa-6a5f-4fd0-b611-ee118a7ebd94', 0, 'Trial and permanent spinal cord stimulator placement have distinct codes, reflecting the genuinely different procedural scope and clinical purpose (temporary assessment vs. permanent therapeutic implantation) — consistent with the recurring temporary-versus-permanent device distinction already established (e.g., tissue expander vs. permanent implant)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('05987f73-fb40-49a8-98c9-0f299b5c8df3', '30d314fa-6a5f-4fd0-b611-ee118a7ebd94', 1, 'Trial and permanent placement are coded identically regardless of which stage is being performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('43d4fb5e-5fd2-4f00-867f-0d5bb183b568', '30d314fa-6a5f-4fd0-b611-ee118a7ebd94', 2, 'Spinal cord stimulator trial has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6737cd4f-1c67-46cd-acb1-62cd7875ee4f', '30d314fa-6a5f-4fd0-b611-ee118a7ebd94', 3, 'Only permanent implantation has a CPT code; the trial phase is never separately billable');
