INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bf932ea8-c3cb-4db4-9b59-010aa4bbcafb', 'ec0d4fee-9843-4197-b870-c8b42757e4cf', 1, 'Percutaneous and surgical lead placement are coded identically regardless of technique');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a8954b60-6e2e-4d1a-906b-7feff218a1e0', 'ec0d4fee-9843-4197-b870-c8b42757e4cf', 2, 'Only surgical/paddle lead placement has a CPT code; percutaneous placement must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b5719b86-5689-4bef-b48f-03bfc5fed371', 'ec0d4fee-9843-4197-b870-c8b42757e4cf', 3, 'Lead placement technique has no bearing on CPT code selection for spinal cord stimulators');
