INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('144f2c0d-7e20-4bdb-acfc-c352cb667dcf', '27b113c7-0fa5-4ec2-aa77-c53c011e9093', 0, 'Pump refill and reprogramming have their own specific code(s), distinct from the initial implantation code, reflecting that this represents ongoing device management rather than the original surgical placement — consistent with the recurring initial-placement-versus-ongoing-management coding distinction already established for other implanted devices');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b26e8ba8-3aeb-45b7-91c2-599e29fa9e6d', '27b113c7-0fa5-4ec2-aa77-c53c011e9093', 1, 'Pump refill/reprogramming is always included in the original implantation code''s global period indefinitely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7d84f1c7-eda9-4b9f-9634-34c4cf964480', '27b113c7-0fa5-4ec2-aa77-c53c011e9093', 2, 'Pump refill is coded identically to the initial implantation procedure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('affcdfec-dc53-45b4-99b8-b18bb4eca348', '27b113c7-0fa5-4ec2-aa77-c53c011e9093', 3, 'Pump refill/reprogramming has no distinct CPT code and must use an unlisted procedure code');
