INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cc66086c-4ae3-4b32-9038-a1a49c245553', '61c89ff7-e09c-4fee-902a-7ff6c250cccf', 0, 'Minimally invasive/microdiscectomy and open discectomy techniques have distinct codes reflecting the different approach, consistent with the approach-specificity theme established throughout this content across many different procedure types');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0f9d30bd-586c-4d23-9d27-beb9360d5fdb', '61c89ff7-e09c-4fee-902a-7ff6c250cccf', 1, 'Microdiscectomy and open discectomy are always coded identically regardless of technique');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e66e5059-4d09-44c4-af59-0f72788cbec5', '61c89ff7-e09c-4fee-902a-7ff6c250cccf', 2, 'Microdiscectomy has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ac6e7574-edce-48df-ba42-078c2fc33398', '61c89ff7-e09c-4fee-902a-7ff6c250cccf', 3, 'Discectomy approach has no bearing on CPT code selection, only the specific spinal level does');
