INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('541efa84-09ac-40ae-9910-2836474bf544', '5c4ea016-4718-4ac4-8ab9-076445917ec7', 0, 'Disc arthroplasty (replacing a diseased disc with an artificial device to preserve motion) has its own specific code, structurally and clinically distinct from spinal fusion (which eliminates motion at the treated level), reflecting these as genuinely different surgical philosophies/techniques for treating degenerative disc disease');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('935e2a44-fb66-468b-b6bc-701b3de1adfd', '5c4ea016-4718-4ac4-8ab9-076445917ec7', 1, 'Disc arthroplasty and spinal fusion are coded identically since both address the same general degenerative disc condition');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f5e93e13-365d-4f2b-bd92-d3a792f5ab04', '5c4ea016-4718-4ac4-8ab9-076445917ec7', 2, 'Disc arthroplasty has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ff42b63d-0689-4bc9-bd82-1423f66a9b68', '5c4ea016-4718-4ac4-8ab9-076445917ec7', 3, 'Disc arthroplasty is coded using the same code as a simple discectomy without any device placement');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
