INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7cf5d217-b4e0-4a45-a055-ea50af05d3d3', '4a7dc506-4169-45aa-846d-e79bf445624e', 0, 'Ventral/incisional hernia repair has its own specific code family, distinct from inguinal hernia repair codes, reflecting the different anatomic hernia location/type — consistent with the general principle that hernia repair codes are structured by specific hernia TYPE/location, not a single universal ''hernia repair'' code regardless of location');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('60ac745e-8a7a-4078-952f-47c090fe01b0', '4a7dc506-4169-45aa-846d-e79bf445624e', 1, 'Ventral/incisional and inguinal hernia repair are coded identically since both are abdominal wall hernias');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('767ebed5-2bf5-4adb-a086-3a63880b69aa', '4a7dc506-4169-45aa-846d-e79bf445624e', 2, 'Ventral hernia repair has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('af289a3c-c776-4d34-876f-6c6a571567a9', '4a7dc506-4169-45aa-846d-e79bf445624e', 3, 'Hernia location has no bearing on CPT code selection, only the presence/absence of mesh does');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('93b4eb08-bc2a-41bc-9944-b19c4482db06', '4c3b40fb-63cd-4c58-aadc-4ecf4b6603ea', 0, 'Hiatal hernia repair (addressing a diaphragmatic hernia, often combined with fundoplication for reflux) has its own distinct code family, structurally and anatomically different from abdominal wall hernia repair codes, reflecting the genuinely different anatomic location and associated procedure (antireflux surgery) typically involved');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2cdff428-6b32-46f9-b316-9a4393ce0def', '4c3b40fb-63cd-4c58-aadc-4ecf4b6603ea', 1, 'Hiatal hernia repair is coded identically to an abdominal wall hernia repair since both are ''hernia repairs''');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('80601569-f6af-454a-a458-01069e997b5f', '4c3b40fb-63cd-4c58-aadc-4ecf4b6603ea', 2, 'Hiatal hernia repair has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e5b8686f-7476-4b69-96fe-d12267676e40', '4c3b40fb-63cd-4c58-aadc-4ecf4b6603ea', 3, 'Hiatal hernia repair is coded using the same code as a diaphragmatic pacing procedure');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5724b1df-2139-409a-a44d-1d067460ac4f', '9204a2b0-29e2-413c-ad38-bab0a688c5ce', 0, 'Depending on the specific code structure, a combined code may exist reflecting both the hiatal hernia repair AND fundoplication performed together, or the two may be separately reportable components — requiring the same combined-versus-component code-descriptor verification already established as a recurring analytical step throughout this content');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c54cf414-e433-4ed2-96ad-226353eac2ba', '9204a2b0-29e2-413c-ad38-bab0a688c5ce', 1, 'Fundoplication and hiatal hernia repair are always coded as entirely separate, unrelated procedures with no combined code ever available');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6d942b5e-4647-4970-b428-7099fd8db4cb', '9204a2b0-29e2-413c-ad38-bab0a688c5ce', 2, 'Only the fundoplication is ever coded, with the hiatal hernia repair considered automatically bundled into it regardless of that code''s own descriptor');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2ffc5c74-36b0-45d1-90e1-547dd430ca85', '9204a2b0-29e2-413c-ad38-bab0a688c5ce', 3, 'Fundoplication has no distinct CPT code and must always use an unlisted procedure code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
