INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('753943cf-ff8e-41f3-92a1-993b9c34f4d1', '88aa7cf2-9bbe-4373-be73-6891c6336996', 0, 'Parastomal hernia repair has its own specific code, distinct from other abdominal wall hernia repair codes (inguinal, umbilical, ventral), reflecting this specific, clinically distinct hernia location/type associated with an existing stoma');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8b7601b6-5726-402b-a96b-3c78c90ba501', '88aa7cf2-9bbe-4373-be73-6891c6336996', 1, 'Parastomal hernia repair is coded identically to a routine ventral hernia repair since both are abdominal wall hernias');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0e9596b4-a0f0-49a1-9f8e-f44863197f97', '88aa7cf2-9bbe-4373-be73-6891c6336996', 2, 'Parastomal hernia repair has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6c02151f-b690-4ad2-a3d5-8b9844458014', '88aa7cf2-9bbe-4373-be73-6891c6336996', 3, 'Parastomal hernia repair coding depends solely on whether the patient''s stoma is a colostomy or ileostomy, with no other coding distinction');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f6fa722e-09de-4bce-9fb0-9e7a0c767e37', '505ffddf-8e05-40e5-82c9-ed35745298c5', 0, 'This reinforces a broader CPT coding principle already seen across many procedure types in this content — even procedures sharing a common general name/category (''hernia repair,'' ''biopsy,'' ''audiology testing'') are frequently split into multiple, anatomically/technically distinct codes, and accurate coding requires identifying the SPECIFIC variant actually documented rather than assuming a single code covers the whole general category');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('29ca247e-bb40-49a3-82d7-c8454eb88a91', '505ffddf-8e05-40e5-82c9-ed35745298c5', 1, 'Hernia repair is uniquely fragmented into many codes, unlike any other procedure category discussed in this content');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('13e2f6bf-24b7-4564-9d2f-fd670aba93db', '505ffddf-8e05-40e5-82c9-ed35745298c5', 2, 'The multiple hernia location-specific codes are functionally interchangeable and may be selected based on coder convenience');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cc827eca-98e4-4f0a-b84c-fc0c61b9bf0d', '505ffddf-8e05-40e5-82c9-ed35745298c5', 3, 'Only inguinal hernia repair has real-world coding relevance; other hernia locations are rarely encountered and not worth distinguishing');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2cd15c9b-d58c-45e1-a764-65b3a5dc9789', '617a4f03-eb65-46d9-a8eb-dcedad37ac68', 0, 'Myelography combined with CT (CT myelogram) may have its own specific combined code, or separate component codes, depending on the specific code structure — requiring the same combined-versus-component verification discipline already established, applied to this specific diagnostic imaging combination');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('df87cfa2-46db-4483-adac-aca3f205d78a', '617a4f03-eb65-46d9-a8eb-dcedad37ac68', 1, 'CT myelogram is always coded as two entirely unrelated procedures (a routine CT and a routine spinal injection) with no recognition of the combined diagnostic study');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('675ca729-9b2e-4ebd-abe2-f8c0a692b38c', '617a4f03-eb65-46d9-a8eb-dcedad37ac68', 2, 'Myelography has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6443c666-8b79-4b33-9d4d-38ae16290043', '617a4f03-eb65-46d9-a8eb-dcedad37ac68', 3, 'CT myelogram is coded identically to a routine, non-contrast spinal CT with no distinction for the myelographic contrast administration');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
