INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dc2df8d7-6650-4b2a-a59a-1309974a04de', 'a02c03a4-5cbd-4dfb-98da-4ef7b3b24a07', 0, 'Mesh revision/removal-and-replacement at a later, separate session has its own specific coding treatment reflecting this distinct later procedural event (not the original repair), consistent with the recurring original-procedure-versus-later-revision coding distinction already established for numerous other device/mesh/hardware scenarios throughout this content');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9dd3d5f3-34d5-4aa6-bd85-c3f49b64907c', 'a02c03a4-5cbd-4dfb-98da-4ef7b3b24a07', 1, 'Mesh revision is always included in the original hernia repair code''s global period indefinitely, regardless of how much later it occurs');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('61b94ecc-a2f9-4307-a0ac-ecc0b318845c', 'a02c03a4-5cbd-4dfb-98da-4ef7b3b24a07', 2, 'Mesh revision is coded identically to the original hernia repair procedure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('34f65b4d-9bfb-4d61-885c-ecb3b0930838', 'a02c03a4-5cbd-4dfb-98da-4ef7b3b24a07', 3, 'Mesh revision has no distinct CPT code and must use an unlisted procedure code in all cases');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7320c2be-318a-418b-81b6-5730edb8281e', '89af11c3-c49d-4541-9c65-7744162d7fd7', 0, 'Surgery-section CPT coding accuracy consistently depends on precisely matching several independently-documented, procedure-specific facts (indication, approach/technique, anatomic location/laterality, device/material used, extent/number of sites treated, and whether a component is bundled or separately reportable) to the correct code descriptor — a disciplined, multi-factor analytical process that applies consistently regardless of surgical specialty, rather than a simple lookup based on the procedure''s general common name alone');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0cceccb2-ca92-4842-9c64-aca7279871bb', '89af11c3-c49d-4541-9c65-7744162d7fd7', 1, 'Each surgical specialty requires an entirely separate, unrelated coding philosophy with no common analytical thread connecting them');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0bcf1b1f-a893-4a77-afdc-922ca7e3d720', '89af11c3-c49d-4541-9c65-7744162d7fd7', 2, 'CPT Surgery-section coding is fundamentally a matter of memorizing individual code numbers rather than applying a consistent analytical framework to documentation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e5a0e7b6-ea90-4815-9dbd-1a6d29bc69a7', '89af11c3-c49d-4541-9c65-7744162d7fd7', 3, 'The specific documented facts of a procedure (approach, device, extent) are largely irrelevant to correct code selection as long as the general procedure category is identified');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('abe2c4fb-35a3-4ee7-99f9-22eec5424b31', '86932d0e-ec0b-4c44-93db-19833f5dbfe2', 0, 'CPT includes a specific code option for the combined ''without contrast, followed by with contrast'' protocol, distinct from the ''without contrast only'' code, reflecting the different, more extensive imaging protocol actually performed — reinforcing the earlier general point that contrast protocol is a defining, code-selection-relevant descriptor element');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c11b86c4-513b-488f-af34-9b850471be7a', '86932d0e-ec0b-4c44-93db-19833f5dbfe2', 1, 'Contrast protocol has no bearing on MRI code selection, only the body part imaged does');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('75da997c-85b5-4951-bcfc-0f617d17ee7d', '86932d0e-ec0b-4c44-93db-19833f5dbfe2', 2, 'The combined without-then-with-contrast protocol is always coded as two entirely separate MRI studies rather than one combined-protocol code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('14de8690-2c4e-471e-8d99-c0e92e89f577', '86932d0e-ec0b-4c44-93db-19833f5dbfe2', 3, 'Only the ''with contrast'' portion is ever coded when both without and with contrast images are obtained in one session');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d9b5da9a-1932-476f-bb68-51636f58d4cb', '3247fc1a-7edb-440e-86e6-5d03c2f071cd', 0, 'PET/CT codes may be structured by clinical indication/body region/purpose (oncologic vs. cardiac vs. neurologic), meaning the specific clinical purpose and body region of the study — not simply ''a PET/CT was performed'' — determines correct code selection');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2e2eb95b-2659-438e-9616-1e189b63b308', '3247fc1a-7edb-440e-86e6-5d03c2f071cd', 1, 'All PET/CT studies, regardless of clinical indication, are coded using a single universal code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cc11f287-1442-41e8-b59c-c1256c831deb', '3247fc1a-7edb-440e-86e6-5d03c2f071cd', 2, 'Oncologic and cardiac PET/CT are coded identically since both use the same PET/CT technology');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a19dec3d-ef0f-44eb-ad8b-e9028001bf03', '3247fc1a-7edb-440e-86e6-5d03c2f071cd', 3, 'PET/CT code selection depends solely on the radiopharmaceutical used, never the clinical indication or body region');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4d1d516f-ee0c-44ea-8a1f-5553c92f7d21', 'a749cd39-5534-401a-baa7-614e2cd863fd', 0, 'The radiopharmaceutical/tracer substance may be separately reportable (often via HCPCS Level II) from the CPT imaging procedure code, reinforcing the same product-plus-service separation pattern already established for nuclear medicine studies generally in Paper 2');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0d393f65-1454-4b38-9d14-e299537ca55b', 'a749cd39-5534-401a-baa7-614e2cd863fd', 1, 'The radiopharmaceutical is always included in the PET imaging code with no separate reporting ever possible');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('861be7a9-066c-48fe-a54a-82b98e700ee5', 'a749cd39-5534-401a-baa7-614e2cd863fd', 2, 'PET radiopharmaceuticals are coded using the same CPT code as the imaging procedure itself with no distinction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8bbe7216-32dc-4a3e-a6a2-adcf12b5e536', 'a749cd39-5534-401a-baa7-614e2cd863fd', 3, 'Radiopharmaceutical administration for PET requires a completely separate anesthesia code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2a730b64-698e-4aaf-bfa9-71abd2893645', 'c517959a-a208-4d8f-b5a6-a5fe8ed868d3', 0, 'fMRI (measuring brain activity/function during specific tasks) has its own specific code, distinct from a routine structural/anatomic brain MRI, reflecting the fundamentally different information being captured (functional activity vs. anatomic structure)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('96f05152-20d9-48c0-9e3c-d34595c5bf30', 'c517959a-a208-4d8f-b5a6-a5fe8ed868d3', 1, 'fMRI and routine structural MRI are coded identically since both use MRI technology on the brain');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d71c3cb9-d278-4c5f-a288-3e0a99d3d1f2', 'c517959a-a208-4d8f-b5a6-a5fe8ed868d3', 2, 'fMRI has no distinct CPT code and must use an unlisted radiology procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0c22dbcc-9a40-4641-ae49-7e6831d26560', 'c517959a-a208-4d8f-b5a6-a5fe8ed868d3', 3, 'fMRI coding depends solely on the total scan duration, not the type of information being captured');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b5f5ee24-43dd-4c44-b9c5-63bfeeb3395d', 'a2435546-6f25-411b-9764-4763b9fc998b', 0, 'MRI-guided breast biopsy has its own specific code/guidance combination distinct from ultrasound-guided or stereotactic guidance, reflecting yet another distinct imaging-guidance modality option within the broader breast biopsy procedure family already discussed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cd08f964-6f43-4a27-a438-8e589bb221de', 'a2435546-6f25-411b-9764-4763b9fc998b', 1, 'MRI-guided, ultrasound-guided, and stereotactic breast biopsy are all coded identically regardless of guidance modality');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8ea283fb-5b26-4506-a8cb-d89141580c27', 'a2435546-6f25-411b-9764-4763b9fc998b', 2, 'MRI-guided breast biopsy has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('426575e2-ce46-450e-8a63-4ac5769d983e', 'a2435546-6f25-411b-9764-4763b9fc998b', 3, 'Guidance modality for breast biopsy has no bearing on CPT code selection, only the needle gauge used');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('161d1b9e-43b7-47de-8e78-fdb6acf60839', '8c7461e1-da63-488f-9b6e-0bfb578e5f9e', 0, 'The imaging report/order should specify the actual protocol/purpose/guidance modality used (contrast timing, functional vs. structural, specific guidance technique), since these documented specifics — not just the general modality and body part — are what determine correct code selection across radiology coding generally');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('55dd0aeb-7cf4-432e-af9a-9429b43da8cd', '8c7461e1-da63-488f-9b6e-0bfb578e5f9e', 1, 'General documentation of ''MRI performed'' or ''PET performed'' is always sufficient regardless of the specific protocol/purpose/guidance used');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('614c5515-c0dc-49e0-8080-e128f8ac8542', '8c7461e1-da63-488f-9b6e-0bfb578e5f9e', 2, 'Protocol/purpose/guidance documentation is relevant only for research studies, never routine clinical imaging');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e079f193-4e19-47fa-9c64-f53886ce4a36', '8c7461e1-da63-488f-9b6e-0bfb578e5f9e', 3, 'Radiology report specificity has no bearing on coding accuracy as long as the correct body part is identified');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a499672f-1cbd-4b48-9097-ea80144da473', 'd065ce78-bdbe-448d-b970-0c6e2d3768bd', 0, 'Neurologic (dementia-evaluation) PET scans may have their own specific code(s) or radiopharmaceutical considerations distinct from oncologic PET/CT, reflecting the different clinical indication and, potentially, different radiopharmaceutical used (e.g., amyloid-specific tracers for dementia evaluation versus FDG for oncologic staging)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('33fd9f15-4f85-4557-bee1-2ca44f582157', 'd065ce78-bdbe-448d-b970-0c6e2d3768bd', 1, 'Neurologic and oncologic PET scans are always coded identically regardless of clinical indication or radiopharmaceutical used');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('393c0cb2-51a8-4a80-88e9-e1c7755c24d7', 'd065ce78-bdbe-448d-b970-0c6e2d3768bd', 2, 'Neurologic PET has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5be9e6a5-241b-4bc1-ac28-a3b6ee53a387', 'd065ce78-bdbe-448d-b970-0c6e2d3768bd', 3, 'PET scan coding depends solely on scanner manufacturer, never clinical indication or radiopharmaceutical');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e8e2c5da-0a7b-4350-8494-b1c402b8c1e6', '4c6c021c-5f59-45bf-b029-6cdfba55a6de', 0, 'MRI arthrography (combining a joint injection procedure with MRI imaging) may involve both an injection procedure code and a specific arthrographic MRI code, or a combined code, depending on the specific code structure — requiring the same combined-versus-component verification discipline already established as a recurring analytical step');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e3508d24-61c6-4632-a180-b2dbe84a550a', '4c6c021c-5f59-45bf-b029-6cdfba55a6de', 1, 'MRI arthrogram and routine joint MRI are coded identically regardless of whether intra-articular contrast injection was performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('50771e50-63b6-4185-aef1-863db27c8357', '4c6c021c-5f59-45bf-b029-6cdfba55a6de', 2, 'MRI arthrography has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('36c4fa9c-2309-4045-bbfe-68ac024ea973', '4c6c021c-5f59-45bf-b029-6cdfba55a6de', 3, 'MRI arthrogram coding depends solely on which joint is imaged, with no distinction for the arthrographic injection component');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5674e5a9-0993-4041-9ac3-20e23343f93b', '876fae00-ef6e-4a5a-ab75-faef9877aad0', 0, 'While primarily a clinical safety matter (screening for renal function, allergy history before contrast administration), documentation of appropriate pre-contrast safety screening also supports the medical-necessity and appropriateness documentation relevant to accurate coding/billing of the contrast-enhanced study, connecting clinical safety practice to coding/compliance documentation more broadly');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dd61f16a-13b5-4d33-a992-6a665cc87dd1', '876fae00-ef6e-4a5a-ab75-faef9877aad0', 1, 'Contrast safety screening has no connection whatsoever to coding or billing documentation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3bdba211-623f-4f1b-8a12-b8847ce0fcaa', '876fae00-ef6e-4a5a-ab75-faef9877aad0', 2, 'Contrast-related safety documentation is solely a radiology department nursing responsibility with zero coding relevance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('10eb5d9d-9a0b-4983-bc16-f5c5736bab7a', '876fae00-ef6e-4a5a-ab75-faef9877aad0', 3, 'Only allergy history, never renal function, is relevant to contrast safety documentation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2cf701cd-442b-4a1b-9657-3203ada1d655', 'b250d750-e17d-4197-bf19-30c61daef94d', 0, 'Apply the same disciplined descriptor-matching approach already established throughout this content''s Radiology-section coverage — identify the specific modality, contrast protocol, functional versus structural purpose, guidance use, and combined-versus-component procedure structure actually documented, then match to the precise code descriptor reflecting those specifics');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3a869679-6e0f-4c6c-9fa0-e428d91095b8', 'b250d750-e17d-4197-bf19-30c61daef94d', 1, 'Assume all MRI and PET studies are billed using a single generic code per body region regardless of protocol, contrast, or purpose');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('74403527-b600-456f-9cd7-ac164e5c7594', 'b250d750-e17d-4197-bf19-30c61daef94d', 2, 'Protocol-specific details are administrative trivia with no real bearing on correct radiology code selection');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('49aa5a0a-8dd8-46dd-b425-683cbbc13ccb', 'b250d750-e17d-4197-bf19-30c61daef94d', 3, 'Rely on the imaging order''s requested study name alone, without confirming it matches what was actually performed and documented');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0c90f361-7847-40b3-9f65-0d4aaf2c4146', 'e374e20e-6cd2-49b9-a884-330c70636fc3', 0, 'If a defined thyroid panel code exists and ALL of its specific component tests were performed, the panel code is reported; if only TSH alone was ordered/performed (not meeting a defined panel''s full component list), only the individual TSH code is reported — reinforcing the panel-component-completeness principle already established generally for laboratory panels');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('502a318c-4f47-44c9-a5da-6f427882cadf', 'e374e20e-6cd2-49b9-a884-330c70636fc3', 1, 'TSH alone and a full thyroid panel are always coded identically regardless of which specific tests were actually performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('24cb0d65-b96a-424a-a167-f31fcf845821', 'e374e20e-6cd2-49b9-a884-330c70636fc3', 2, 'Only a full thyroid panel has any CPT code; TSH alone can never be separately coded');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('28590efc-826b-4bcd-a559-b75345b7ff40', 'e374e20e-6cd2-49b9-a884-330c70636fc3', 3, 'Panel coding for endocrine tests follows entirely different rules from the general panel-completeness principle already established for other panels (e.g., BMP/CMP)');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('adb83226-ccd4-43e9-a79c-5eff2879a7da', 'af59de4c-77f3-4c90-8b96-ef0bd44b61d2', 0, 'HbA1c and fasting glucose are distinct, separately defined tests measuring different things (long-term average glycemic control vs. a single point-in-time glucose level), each with its own specific code, reflecting genuinely different clinical information despite both relating to diabetes monitoring');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('067687de-c8a8-4f2c-9854-4a54a0208145', 'af59de4c-77f3-4c90-8b96-ef0bd44b61d2', 1, 'HbA1c and fasting glucose are coded identically since both relate to diabetes management');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e72c0015-a8d5-4dc4-991a-28e6b27eb5c1', 'af59de4c-77f3-4c90-8b96-ef0bd44b61d2', 2, 'HbA1c has no distinct CPT code and must use an unlisted laboratory procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('23fc7102-63e6-40db-a28a-93731edcdcfa', 'af59de4c-77f3-4c90-8b96-ef0bd44b61d2', 3, 'Fasting glucose and HbA1c are always ordered and coded together as a single combined panel with no separate reporting option');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4ae48103-3a27-4716-82f1-fbaa3c0fd067', '6474c0e3-f0ad-4594-9aca-401803346288', 0, 'The lipid panel code requires that its specific defined component tests actually be performed; if only a subset (e.g., total cholesterol alone) was ordered/performed, only the individual component code(s) actually performed are reported, not the full panel code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('425d3379-3d15-4b12-9d33-97ae123eae09', '6474c0e3-f0ad-4594-9aca-401803346288', 1, 'The lipid panel code may be reported regardless of how many of its component tests were actually performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ffa5e718-ec0b-4359-a827-3d0f69b9a7e6', '6474c0e3-f0ad-4594-9aca-401803346288', 2, 'Lipid panel components can never be individually coded; only the full panel code exists');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8d0482d0-c884-4dd4-8712-78560fc6a73c', '6474c0e3-f0ad-4594-9aca-401803346288', 3, 'Lipid panel coding depends solely on the patient''s fasting status, not which specific components were tested');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('39b77881-a262-47dc-a328-53a8be087586', '11d8db09-dc5d-4e9a-bed1-c6b06978de01', 0, 'PTH and calcium (total or ionized) are distinct, separately coded tests measuring different substances, even though they are often clinically interpreted together for calcium/parathyroid disorder evaluation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d28fa0c4-f97d-4300-9d8b-b486f8e90ff8', '11d8db09-dc5d-4e9a-bed1-c6b06978de01', 1, 'PTH and calcium testing are coded identically since both relate to calcium metabolism');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0b5ae1be-08bb-4913-adb8-9d9189051b89', '11d8db09-dc5d-4e9a-bed1-c6b06978de01', 2, 'PTH has no distinct CPT code and must use an unlisted laboratory procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5b890587-0f0b-443e-9655-75d877bc3bca', '11d8db09-dc5d-4e9a-bed1-c6b06978de01', 3, 'Ionized and total calcium are coded identically with no distinction between these two calcium measurement methods');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8ca9fe91-c221-4493-9233-70cf5b92fdce', 'ad78de65-327a-4fe4-b321-f3ad7de80fd2', 0, 'Each distinct cortisol measurement (e.g., AM draw and PM draw) may be separately reportable as distinct specimens/tests, since these represent genuinely separate laboratory analyses performed at clinically specified different times, rather than being combined into a single code regardless of how many separate draws/measurements were performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1eff5adf-92ab-4848-a644-c9cfc0975ba1', 'ad78de65-327a-4fe4-b321-f3ad7de80fd2', 1, 'AM and PM cortisol are always combined into a single code regardless of how many separate draws were performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('20605b15-7bdd-4b7e-ae4d-380e2f68731d', 'ad78de65-327a-4fe4-b321-f3ad7de80fd2', 2, 'Cortisol testing has no distinct CPT code and must use an unlisted laboratory procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('afe183fb-2753-442f-8772-520e237b423e', 'ad78de65-327a-4fe4-b321-f3ad7de80fd2', 3, 'Only one cortisol measurement per day may ever be coded, regardless of the clinical protocol requiring multiple timed draws');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('585fa21a-1d8f-4ee4-93d8-01f42d2fdbec', '8deab9d9-c2b8-4b4d-b2f8-eab6dfccd2d4', 0, 'GTT has its own specific code(s) reflecting the multi-timepoint testing protocol as a defined test structure, distinct from simply reporting multiple individual glucose test codes for each timepoint, since the GTT represents a specifically defined, protocol-based test');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3834b3a2-7aaf-44ea-bea8-79796e363cbd', '8deab9d9-c2b8-4b4d-b2f8-eab6dfccd2d4', 1, 'GTT is coded by reporting the individual glucose code once for each timepoint measured, with no distinct GTT-specific code structure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a111adad-88ff-4ecd-8d43-36eb2fcbb143', '8deab9d9-c2b8-4b4d-b2f8-eab6dfccd2d4', 2, 'GTT has no distinct CPT code and must use an unlisted laboratory procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3bff2f03-e54a-4654-8a0a-190f604f3aac', '8deab9d9-c2b8-4b4d-b2f8-eab6dfccd2d4', 3, 'GTT coding depends solely on the number of hours the test protocol spans, not the specific timepoints/glucose challenge protocol used');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fca179c0-bce2-43bc-a240-4291e60719a7', 'd13d4c74-b0b1-49e0-b349-3a8ffa0f10fd', 0, 'The laboratory requisition/report should specify exactly which specific tests/timepoints were actually performed, since — consistent with the recurring documentation-specificity theme established across panels, reflex testing, and toxicology — this specific detail (not a general category label like ''endocrine workup'') determines correct code selection');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5d6a825c-91da-4fb0-9771-ffe0fc8435c9', 'd13d4c74-b0b1-49e0-b349-3a8ffa0f10fd', 1, 'General documentation of ''endocrine testing performed'' is sufficient regardless of which specific tests/timepoints were actually performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f7dc6060-de47-426f-89e4-6c889c9e76a4', 'd13d4c74-b0b1-49e0-b349-3a8ffa0f10fd', 2, 'Endocrine/metabolic testing follows entirely different documentation standards from the panel/reflex/toxicology documentation principles already established elsewhere in this content');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b4e3af92-d056-44c6-be46-7d0804694395', 'd13d4c74-b0b1-49e0-b349-3a8ffa0f10fd', 3, 'Timing/protocol documentation is relevant only for research-context testing, never routine clinical endocrine evaluation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('324fe026-8806-428d-8f37-99b08076169f', '0ceaa1ab-c5ab-415d-840d-d82c049e1b70', 0, 'Tumor markers have their own specific, distinct codes per the specific marker being tested, reflecting specialized oncology-monitoring laboratory tests structurally separate from general chemistry panel components (BMP/CMP) or routine hormone tests');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('99202a06-5a21-488c-b430-bf9e04c89437', '0ceaa1ab-c5ab-415d-840d-d82c049e1b70', 1, 'Tumor markers are coded identically to a general chemistry panel component test');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fb49cd9a-e27e-41eb-adeb-44ae545238fb', '0ceaa1ab-c5ab-415d-840d-d82c049e1b70', 2, 'Tumor marker testing has no distinct CPT code and must use an unlisted laboratory procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('eed99bfb-b9e1-481a-a6be-13a119bbd0e7', '0ceaa1ab-c5ab-415d-840d-d82c049e1b70', 3, 'All tumor markers, regardless of which specific marker, are coded using a single universal ''tumor marker'' code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b2edf9ef-2c17-40f5-a279-4f435995819b', 'c56db6a4-9fd5-4d47-abc9-aeb3445dbc34', 0, 'Screening and diagnostic PSA testing may have different applicable coding/coverage treatment despite using the same underlying laboratory test, mirroring the screening-versus-diagnostic distinction already established for other services (mammography, colonoscopy) — coding/billing should reflect the actual clinical purpose of each specific encounter');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cefc4e7b-8a3b-4e7f-89cc-8835d570bae1', 'c56db6a4-9fd5-4d47-abc9-aeb3445dbc34', 1, 'Screening and diagnostic PSA are always coded and covered identically regardless of clinical purpose');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e134be2f-883a-4e0b-b392-270f4695ead8', 'c56db6a4-9fd5-4d47-abc9-aeb3445dbc34', 2, 'Only diagnostic PSA testing has a CPT code; screening PSA has no corresponding code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2332f3cd-5b16-4304-95b1-dd820e03c320', 'c56db6a4-9fd5-4d47-abc9-aeb3445dbc34', 3, 'PSA testing purpose (screening vs. diagnostic) is relevant only to patient counseling, never to coding or coverage');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6c892cc2-13f7-46c5-9322-e3b31521b93a', '1b733363-9d98-4f57-83ef-2e3e94d163d3', 0, 'Apply the same disciplined analytical approach already established throughout this content''s Pathology & Laboratory coverage — verify the specific analyte(s)/component(s) actually tested against defined panel lists, recognize distinct-but-related analytes as separately coded, account for timed/multi-specimen protocols as their own defined test structures, and consider screening-versus-diagnostic purpose where relevant — rather than assuming broad category labels (endocrine, tumor marker, metabolic) map to a single code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cbc63053-1043-45f3-ade6-1dc5f28fac49', '1b733363-9d98-4f57-83ef-2e3e94d163d3', 1, 'Endocrine and tumor marker testing require an entirely separate analytical approach unrelated to the panel/reflex/toxicology principles already established');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ac856bbe-87b3-4dcb-82a3-70aafc1f3f41', '1b733363-9d98-4f57-83ef-2e3e94d163d3', 2, 'Assume all tests within a broad category like ''endocrine testing'' or ''tumor marker testing'' are interchangeable and coded identically');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('279857a4-b920-4d76-b9c3-fc50b7a95900', '1b733363-9d98-4f57-83ef-2e3e94d163d3', 3, 'Rely on the ordering physician''s diagnosis code alone to determine the correct laboratory test code, without confirming which specific test was actually performed');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ea5bcd0c-02c1-4cf0-8234-a99149ea5bd5', '0ce47c15-221c-414e-b9eb-a67806f80d19', 0, 'A billing convention (used by Medicare and many other payers) for determining how many units of a timed CPT code may be billed based on total minutes of therapy provided — generally requiring at least 8 minutes of a service to bill one unit, with specific minute thresholds for each additional unit');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ebcea708-9a47-4f94-9787-626abe00626b', '0ce47c15-221c-414e-b9eb-a67806f80d19', 1, 'A rule requiring therapy sessions to last exactly 8 minutes, no more and no less');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('935a09b4-3ad1-4275-993a-2287e7f5cbe9', '0ce47c15-221c-414e-b9eb-a67806f80d19', 2, 'A rule that applies only to occupational therapy, never physical therapy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('70c847fd-c41e-4fe6-a468-05699628781a', '0ce47c15-221c-414e-b9eb-a67806f80d19', 3, 'A rule determining which specific therapeutic exercise codes may be used, unrelated to time/units');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f134f9c7-aac7-4dbd-9cc8-dc81ff1adae5', 'c140908e-9382-40cd-91f3-7716e46a6abc', 0, 'Both may be separately reportable — the timed code based on actual minutes/units per the 8-minute rule, and the untimed code reported once regardless of duration — since these represent genuinely different billing structures (time-based vs. service-based) within the same visit, consistent with the timed-versus-untimed distinction already established generally');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b5bd06cd-1fe7-4ca8-a7cf-c2303ce2e492', 'c140908e-9382-40cd-91f3-7716e46a6abc', 1, 'Only one code, timed or untimed, may ever be reported per visit regardless of how many distinct services were performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5fc535f6-844f-4c1a-a077-5f5050eda36e', 'c140908e-9382-40cd-91f3-7716e46a6abc', 2, 'Untimed codes are always bundled into any timed code reported during the same visit');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('57ae6984-6a0b-44ca-a984-0fcfb65555e7', 'c140908e-9382-40cd-91f3-7716e46a6abc', 3, 'Timed and untimed codes can never both be reported for the same patient on the same date');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('549ed91a-54e3-4af2-8063-18255369a46c', 'c34c1dfb-a340-4b23-bee7-2a01b50a1405', 0, 'Therapeutic exercise (general strengthening/conditioning/flexibility) and neuromuscular reeducation (retraining movement, balance, coordination, proprioception, often for neurologic conditions) are distinct, separately defined timed codes reflecting different treatment techniques, even though both may be part of the same overall treatment plan');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7cf289f6-4337-4a77-8983-0530f393f78e', 'c34c1dfb-a340-4b23-bee7-2a01b50a1405', 1, 'Therapeutic exercise and neuromuscular reeducation are coded identically since both are physical therapy interventions');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c4a66905-fb02-446d-9014-2174c2e8b376', 'c34c1dfb-a340-4b23-bee7-2a01b50a1405', 2, 'Neuromuscular reeducation has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ce944cbf-b44a-40ab-8dda-456e6ad690a7', 'c34c1dfb-a340-4b23-bee7-2a01b50a1405', 3, 'The choice between these two codes depends solely on which body part is being treated, not the actual technique performed');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fc72341e-e997-461e-9c60-14484789ada4', 'd1839059-77ef-4f7d-92af-e263b9514f5a', 0, 'Manual therapy has its own specific timed code, distinct from therapeutic exercise, reflecting a genuinely different hands-on treatment technique (practitioner-applied mobilization) from active/guided patient exercise');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('59b83358-9779-47f2-aa6b-1b4ccba60f11', 'd1839059-77ef-4f7d-92af-e263b9514f5a', 1, 'Manual therapy and therapeutic exercise are coded identically regardless of technique performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a453bab0-cb02-4daa-9fd2-655d54cc1911', 'd1839059-77ef-4f7d-92af-e263b9514f5a', 2, 'Manual therapy has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d6345313-d702-448c-8f2f-6afbf1fc2f0f', 'd1839059-77ef-4f7d-92af-e263b9514f5a', 3, 'Manual therapy is coded using the same code as neuromuscular reeducation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('be1ce846-9173-4da1-a7a8-901965362f65', 'de74b73f-9479-4055-8e61-920e8ea0b3f4', 0, 'PT evaluation codes (often tiered by complexity — low, moderate, high complexity, depending on the specific code structure) are distinct from the ongoing timed treatment codes, reflecting the different service type (initial assessment/plan-of-care development vs. ongoing treatment intervention)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ca6752af-1604-4f56-b718-85fe4af92a0d', 'de74b73f-9479-4055-8e61-920e8ea0b3f4', 1, 'PT evaluation is coded using the same timed therapeutic exercise code as ongoing treatment');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a9b341cb-f5a7-4d70-abad-417bdf5e5d00', 'de74b73f-9479-4055-8e61-920e8ea0b3f4', 2, 'PT evaluation has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('64a82640-0810-428e-83ae-0c4814d2ce93', 'de74b73f-9479-4055-8e61-920e8ea0b3f4', 3, 'PT evaluation complexity has no bearing on code selection; a single universal evaluation code applies regardless of documented complexity');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('01a61f8f-7e80-4f20-88c7-823f48bbfcb1', 'f0aa0cdc-d2b8-4604-9934-dedd74fbec07', 0, 'OT has its own overlapping-but-distinct set of timed and untimed codes (including ADL/self-care training codes), reflecting occupational therapy''s own distinct scope of practice (functional/daily-living skills) even where some codes may be used by either PT or OT practitioners depending on the specific service and state scope-of-practice rules');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b853db6d-4fe7-4d23-ab3c-09bea1f3a1b8', 'f0aa0cdc-d2b8-4604-9934-dedd74fbec07', 1, 'OT and PT always use an entirely separate, non-overlapping, mutually exclusive code set with zero shared codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5e0a52b7-acf3-4f3b-b89f-25cfd364eeec', 'f0aa0cdc-d2b8-4604-9934-dedd74fbec07', 2, 'OT has no distinct CPT codes and must use PT codes for all services');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8060bdf3-f7f0-4edb-a35d-4a5da9e4cea3', 'f0aa0cdc-d2b8-4604-9934-dedd74fbec07', 3, 'ADL training has no distinct CPT code and must use an unlisted procedure code regardless of which discipline performs it');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fb79443f-df36-44f6-b22f-6ead0c507496', 'e3e32d7e-ebe4-4367-9ed2-75ba8595426b', 0, 'Documentation should specify the actual total minutes of the specific timed service provided during the visit, since accurate unit calculation depends on this documented duration matched against the applicable minute-threshold table — a general statement of ''therapy provided'' without minute documentation wouldn''t support accurate unit billing');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('11439703-4a5b-47b1-b374-07207ae93a9d', 'e3e32d7e-ebe4-4367-9ed2-75ba8595426b', 1, 'No minute documentation is needed since timed codes are always billed as a single flat unit regardless of actual duration');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5287c50f-1b22-4e42-9ba8-3bb84a60ff70', 'e3e32d7e-ebe4-4367-9ed2-75ba8595426b', 2, 'Only the total visit length (not the specific timed service''s own duration) is relevant to unit calculation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('83a13b7e-3e79-4fbc-8094-abdf4b7d9c63', 'e3e32d7e-ebe4-4367-9ed2-75ba8595426b', 3, 'Unit calculation depends solely on the therapist''s subjective assessment of session intensity, not documented time');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b770e5d3-2625-4ad8-88be-92bcd9ca5542', '6961a67c-51ef-4985-a671-f72645786a9f', 0, 'Given the direct mathematical relationship between documented time and billed units, periodic auditing of whether documented minutes genuinely and consistently support the number of units billed (rather than a pattern of consistently rounding up regardless of actual time) is a reasonable, targeted compliance practice, similar in concept to the other targeted-audit-area rationale already established (e.g., ventilator hours, POA accuracy)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('777793e7-32f7-4ae9-82a8-ea78c2cffb77', '6961a67c-51ef-4985-a671-f72645786a9f', 1, 'Timed therapy code billing carries no distinct compliance considerations from any other service type');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fe70e9b6-880f-44b2-ae37-96fb7f608555', '6961a67c-51ef-4985-a671-f72645786a9f', 2, 'Units billed should always be maximized regardless of documented time, since more units always benefits the patient''s care');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9432b730-f9bc-45dd-a403-c3044df0f625', '6961a67c-51ef-4985-a671-f72645786a9f', 3, 'The 8-minute rule has no real-world compliance/audit relevance since it''s purely an internal calculation method');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('95575ea4-a40e-46a6-b8a4-694310eae664', 'a7f97cd8-eae4-4a6d-9ea3-ac5fa074996a', 0, 'Group therapy has its own specific code, distinct from individual (one-on-one) timed therapy codes, reflecting the different service structure (supervision of multiple patients simultaneously versus one-on-one direct patient contact) — consistent with the general principle that service STRUCTURE (not just the general treatment technique) affects correct code selection');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('18b62de3-1289-4a03-8741-18fd094f9164', 'a7f97cd8-eae4-4a6d-9ea3-ac5fa074996a', 1, 'Group and individual therapy are coded identically since both involve therapeutic exercise activities');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('eab95af5-d81b-46da-955e-59f8d536e8fc', 'a7f97cd8-eae4-4a6d-9ea3-ac5fa074996a', 2, 'Group therapy has no distinct CPT code and must use an unlisted procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('20523cd2-5259-4ca2-b1f6-1e410e3671a4', 'a7f97cd8-eae4-4a6d-9ea3-ac5fa074996a', 3, 'Group therapy coding depends solely on the number of patients in the group, with no distinct code from individual therapy regardless of group size');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('460374fd-28d6-4e2a-982a-4eefe5877857', '31f60afe-150a-488e-bcc3-d4b5c380e4ec', 0, 'Apply the same disciplined analytical approach already established throughout this content''s Medicine-section coverage — identify the specific technique/service structure (timed vs. untimed, individual vs. group, evaluation vs. ongoing treatment, PT-specific vs. OT-specific vs. shared codes), accurately document actual time for timed codes per the 8-minute rule, and match to the correct specific code — rather than treating ''physical therapy'' as a single undifferentiated billing category');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c15fe367-9fb4-4169-ace9-c126256e8552', '31f60afe-150a-488e-bcc3-d4b5c380e4ec', 1, 'All physical/occupational therapy services are billed as a single flat per-visit fee with no distinction for technique, time, or service structure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('19b43616-c243-4d4e-b11f-6f3e1b4b49db', '31f60afe-150a-488e-bcc3-d4b5c380e4ec', 2, 'Physical/occupational therapy coding requires an entirely separate analytical framework unrelated to the broader Medicine-section principles already established');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('21140e2a-1475-4407-b9f0-bd75da5a9ece', '31f60afe-150a-488e-bcc3-d4b5c380e4ec', 3, 'Rely on the therapist''s own internal documentation template defaults rather than confirming actual technique/time/structure matches the code being billed');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8d6c9a71-105c-4aff-952f-a6168d5aca1b', '7910b0f9-b2a1-48d2-b089-21a5cda10c78', 0, 'The global period defines the number of days after a procedure during which related follow-up care and complications are generally bundled into the original procedure''s payment, with the specific duration (0/10/90 days) varying by procedure based on its typical postoperative course');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fe5202dd-c3b8-48e9-8b6c-b5c9083a4aad', '7910b0f9-b2a1-48d2-b089-21a5cda10c78', 1, 'The global period refers to the total time the surgery itself takes to perform, not the postoperative follow-up window');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('72f1e219-29dc-44c0-ac74-633ba3bfdc33', '7910b0f9-b2a1-48d2-b089-21a5cda10c78', 2, 'All CPT surgical codes have an identical global period length regardless of procedure complexity');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('23f22d01-7120-4409-8bcb-f700383021e0', '7910b0f9-b2a1-48d2-b089-21a5cda10c78', 3, 'The global period has no bearing on which modifiers (24, 58, 78, 79) are appropriate, since these modifiers apply regardless of global period status');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('50e32066-734b-4bef-a472-a369fbbd1abf', '27135017-574a-471b-a110-526de02b8775', 0, 'Because routine, RELATED postoperative E/M care is already bundled into the global surgical package payment — modifier 24 exists specifically to flag the exception (a genuinely unrelated condition) that should be separately payable, not to bypass the bundling for related follow-up care');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bb8df52e-add7-46cd-87f2-f357d2d64fca', '27135017-574a-471b-a110-526de02b8775', 1, 'Modifier 24 may be used for any E/M service during the global period regardless of relatedness, as long as the modifier is appended');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ad01d61d-6d52-4068-93c5-333bafdca9ce', '27135017-574a-471b-a110-526de02b8775', 2, 'Relatedness has no bearing on modifier 24''s appropriate use');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6ef7aa6c-0004-46da-93d8-879399b35549', '27135017-574a-471b-a110-526de02b8775', 3, 'Modifier 24 is used specifically FOR related postoperative visits, the opposite of its actual definition');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('663d3720-3225-45ba-afe9-b3b85b8bea34', '26f2eaf6-317a-4ca9-89a9-c61de1d8eead', 0, 'Modifier 24 is appropriately appended to the E/M code for this visit, since the pneumonia is genuinely unrelated to the surgical procedure, allowing separate payment for this E/M service despite occurring within the global period');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0003ef8e-ddfe-4ab7-b6ac-4bf84c05a644', '26f2eaf6-317a-4ca9-89a9-c61de1d8eead', 1, 'No E/M service may be separately billed during any global period regardless of relatedness');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3dfe690b-d785-4f27-a4eb-b19f652cac43', '26f2eaf6-317a-4ca9-89a9-c61de1d8eead', 2, 'Modifier 58 (staged/related procedure) is the correct modifier for this unrelated-condition scenario');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ec90d24a-8242-4360-bd5a-12183fcf30ef', '26f2eaf6-317a-4ca9-89a9-c61de1d8eead', 3, 'The pneumonia diagnosis must be ignored entirely until the global period ends, with no E/M service coded');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f8b5673f-754d-4429-a91a-3ed1d65bf715', '0187ce06-7821-4f7c-a3a5-69831f468b6d', 0, 'This would improperly bypass the global-period bundling logic, seeking separate payment for a service that should already be included in the original procedure''s global payment — a real compliance/overpayment risk pattern, similar in principle to the NCCI-bypass-modifier misuse pattern already established generally');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('185d2fcd-7be6-4438-afa6-8eb379e224e4', '0187ce06-7821-4f7c-a3a5-69831f468b6d', 1, 'No compliance risk exists since modifier 24 may be applied to any E/M service during a global period regardless of actual relatedness');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f91b4792-41d7-4dff-b42f-707d1fd1089c', '0187ce06-7821-4f7c-a3a5-69831f468b6d', 2, 'This scenario is compliant as long as the physician personally believes the visit warrants separate payment, regardless of actual documented relatedness');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('caf3c6ab-c30c-47e0-9a58-6e993a8c3d08', '0187ce06-7821-4f7c-a3a5-69831f468b6d', 3, 'Modifier 24 misuse carries no meaningful financial impact since global periods don''t actually affect payment amounts');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('34ec8025-edf9-4ed9-807a-764ee04ef0c3', '97b69d9d-8fef-4121-8850-5398feeacec2', 0, 'Documentation should clearly establish the clinical basis for why the E/M service addresses a condition genuinely unrelated to the original surgical procedure (e.g., a distinct diagnosis with no plausible connection to the surgery or its typical recovery course), not simply noting that the visit occurred during the global period');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1d81581f-2bda-480a-af1d-b6da2d10fdf1', '97b69d9d-8fef-4121-8850-5398feeacec2', 1, 'No specific documentation is needed since modifier 24''s applicability is assumed whenever a postoperative visit occurs, regardless of clinical relatedness');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2b7940d7-3402-4545-bab6-820be3cc1a11', '97b69d9d-8fef-4121-8850-5398feeacec2', 2, 'Modifier 24 documentation requirements are identical to modifier 58''s documentation requirements, since both relate to postoperative periods');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fd451810-abc3-4370-a6fd-7cef5f672dc1', '97b69d9d-8fef-4121-8850-5398feeacec2', 3, 'Only the date of the visit relative to the surgery date needs to be documented; clinical relatedness itself requires no specific documentation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('01775564-e2c6-43d3-9f0d-31aed30d418e', '421f1899-122e-4057-bf27-b6f2f04cbf61', 0, 'Modifier 78 addresses an UNPLANNED return to the OR for a procedure RELATED to the original surgery (e.g., a complication requiring reoperation), while modifier 79 addresses a procedure UNRELATED to the original surgery performed by the same physician during that postoperative period — related-unplanned versus unrelated is the key distinguishing factor between these two modifiers');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('299a968c-c651-4605-852d-4b18939081c5', '421f1899-122e-4057-bf27-b6f2f04cbf61', 1, 'Modifiers 78 and 79 are fully interchangeable with no meaningful distinction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('75d11b0b-6ebd-4414-815d-1a0575c02494', '421f1899-122e-4057-bf27-b6f2f04cbf61', 2, 'Modifier 78 addresses unrelated procedures while modifier 79 addresses related procedures — the reverse of their actual definitions');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b4e4f6e5-882b-45b2-bc6c-5cc5ca1c7966', '421f1899-122e-4057-bf27-b6f2f04cbf61', 3, 'Both modifiers require the procedure to occur in a different facility from the original surgery to be appropriately used');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('755b5574-2485-486a-8a00-5fed73a49d61', '3234bb7f-b772-4b93-bdb3-17c77ccf0911', 0, 'The staged procedure (with modifier 58 appropriately appended) establishes its OWN new global period starting from that procedure''s date, meaning subsequent related/unrelated postoperative scenarios are then evaluated relative to THIS most recent procedure, not the original one — global periods can effectively ''restart'' with each new staged or unplanned procedure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e17b5cec-a107-4a8e-8290-fba6157dace3', '3234bb7f-b772-4b93-bdb3-17c77ccf0911', 1, 'The original procedure''s global period continues unchanged regardless of any staged procedures performed during it, with no new global period ever starting');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9f0ac557-04a0-485d-b9fb-2b1b46e9c75c', '3234bb7f-b772-4b93-bdb3-17c77ccf0911', 2, 'Staged procedures never have their own global period; only the very first procedure in a treatment course ever has a global period');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9100526d-c249-441b-b6b9-464550172a1b', '3234bb7f-b772-4b93-bdb3-17c77ccf0911', 3, 'Global period restart rules apply only to modifier 78 scenarios, never modifier 58 scenarios');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b2a6959a-d286-4f03-884b-8397a4839181', 'e7b3ba6a-12bb-4e57-bc6f-ba5337cdbd40', 0, 'Clear documentation of each procedure''s date and its relationship to prior procedures (planned/staged vs. unplanned complication vs. unrelated) supports both accurate modifier selection (58/78/79/24) for each subsequent encounter AND accurate tracking of which procedure''s global period is currently active, given that global periods can restart with each new procedure as already established');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6b88d1e6-1793-4b39-a143-69dd9383e881', 'e7b3ba6a-12bb-4e57-bc6f-ba5337cdbd40', 1, 'No date-specific documentation is needed since global period tracking is solely an automated billing-system function requiring no clinical documentation input');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('109e34ee-bb58-4543-a00c-5be253a46b86', 'e7b3ba6a-12bb-4e57-bc6f-ba5337cdbd40', 2, 'Global period tracking is only relevant for single-procedure episodes, never multi-stage treatment courses like staged reconstruction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0d606f11-ae4d-4c7e-a93a-2cc8737c1b3f', 'e7b3ba6a-12bb-4e57-bc6f-ba5337cdbd40', 3, 'Multi-stage procedures are exempt from global period rules entirely, with every stage always separately, fully payable regardless of modifiers');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('39a26fc2-0603-4634-a003-912bfc29bc14', '648cefb7-bb2d-43d4-a0a2-70f091afdfa7', 0, 'Reviewing whether these modifiers are applied with genuine, consistent documentation support (correct relatedness/planned-status characterization) rather than a pattern of routine, reflexive application to maximize separate payment for services that should properly be bundled — consistent with the general modifier-outcome-pattern-monitoring principle already established for other modifier categories throughout this content');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4fc6fcfe-c7a0-4cf9-9ad9-d65e26dd6757', '648cefb7-bb2d-43d4-a0a2-70f091afdfa7', 1, 'Global-period modifier usage patterns have no meaningful compliance-monitoring value');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('662589d1-6488-43fc-93b4-c9733f2d0d75', '648cefb7-bb2d-43d4-a0a2-70f091afdfa7', 2, 'These modifiers should be applied to the maximum number of postoperative encounters possible, regardless of documented relatedness/planned status, to ensure no separate payment is missed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('02ba51c9-486c-4fe8-8d43-8804bd1337d4', '648cefb7-bb2d-43d4-a0a2-70f091afdfa7', 3, 'Only modifier 78, never 24/58/79, carries any compliance significance');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2bcf7bca-7b50-4eaf-88c1-99eeb1d114aa', '8a91ae38-b642-4162-908b-63a584857cb8', 0, 'Every modifier category examined throughout this series exists to accurately communicate a SPECIFIC, genuinely-occurring documented circumstance (relatedness/planned-status, clinical distinctness, or physician role) to support correct claims adjudication — and in every category, the recurring compliance risk is the SAME underlying pattern: applying a modifier reflexively or for reimbursement optimization rather than because the specific documented facts genuinely, accurately support it');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b25e2bd3-23e3-4e65-898c-0395381db3fe', '8a91ae38-b642-4162-908b-63a584857cb8', 1, 'Each modifier category is entirely unrelated to the others, requiring separate, unconnected analytical frameworks with no shared underlying principle');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('656164ff-14ec-4f83-ab57-3494a3cfd569', '8a91ae38-b642-4162-908b-63a584857cb8', 2, 'Modifiers exist primarily to increase reimbursement and should be applied whenever doing so would benefit the practice financially, regardless of documented circumstances');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4a816092-b741-4faa-9949-8338dd4a2b8b', '8a91ae38-b642-4162-908b-63a584857cb8', 3, 'Compliance risk from modifier misuse is a concern only for NCCI-bypass modifiers; global-period and physician-role modifiers carry no comparable risk');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
