VALUES ('818e3e13-642e-48d8-afef-f1fd2cf82a31', '161a5441-b93a-4090-955b-3ea097d0b2fe', 39, 'Which of the following best describes correct coding for bilateral inguinal hernia repair performed during the same operative session?');
