VALUES ('5c4ea016-4718-4ac4-8ab9-076445917ec7', '161a5441-b93a-4090-955b-3ea097d0b2fe', 52, 'Which of the following best describes correct coding for an artificial disc replacement (disc arthroplasty) procedure, as distinguished from spinal fusion?');
